'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useApp } from 'context/AppContext';
import { GlossyPillButton } from 'components/ui/GlossyPillButton';
import { 
  ShieldCheck, 
  Lock, 
  Mail, 
  Eye, 
  EyeOff, 
  ArrowRight, 
  AlertTriangle, 
  ArrowLeft,
  KeyRound,
  CheckCircle2,
  Sparkles
} from 'lucide-react';

export default function AdminLoginPage() {
  const router = useRouter();
  const { login, currentUser, setRole } = useApp();

  const [adminEmail, setAdminEmail] = useState('');
  const [adminPassword, setAdminPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  const handleAdminLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setErrorMessage(null);

    const cleanEmail = adminEmail.trim().toLowerCase();

    // Validate admin domain or credentials
    if (!cleanEmail.includes('admin') && cleanEmail !== 'admin@coachconnect.org') {
      setIsLoading(false);
      setErrorMessage('Access denied. This portal is strictly restricted to platform administrators.');
      return;
    }

    const res = await login(cleanEmail, adminPassword);
    setIsLoading(false);

    if (res.success) {
      setSuccessMessage('✓ Administrator verified. Redirecting to Admin Hub...');
      setRole('admin');
      setTimeout(() => {
        router.push('/admin');
      }, 1000);
    } else {
      setErrorMessage(res.error || 'Invalid administrator credentials. Access denied.');
    }
  };

  const handleAutofill = () => {
    setAdminEmail('admin@coachconnect.org');
    setAdminPassword('CoachAdmin@2026');
    setErrorMessage(null);
  };

  return (
    <div className="min-h-screen bg-[#0F172A] text-slate-100 flex flex-col justify-between font-sans antialiased relative overflow-hidden">
      
      {/* Background Glow Accents */}
      <div className="absolute -top-40 -right-40 w-96 h-96 bg-red-600/15 rounded-full blur-3xl pointer-events-none" />
      <div className="absolute -bottom-40 -left-40 w-96 h-96 bg-indigo-600/15 rounded-full blur-3xl pointer-events-none" />

      {/* Top Navbar */}
      <header className="h-20 border-b border-slate-800/80 px-6 sm:px-12 flex items-center justify-between backdrop-blur-md relative z-10">
        <Link href="/" className="flex items-center gap-2.5 group">
          <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-red-600 to-rose-500 flex items-center justify-center text-white shadow-md shadow-red-500/20">
            <ShieldCheck className="w-5 h-5" />
          </div>
          <div>
            <span className="text-xl font-bold tracking-tight text-white flex items-center">
              Coach<span className="text-red-500">Connect</span>
            </span>
            <span className="block text-[10px] font-bold text-red-400 tracking-wider uppercase -mt-0.5">
              Admin Gateway
            </span>
          </div>
        </Link>

        <Link
          href="/"
          className="text-xs font-semibold text-slate-400 hover:text-white flex items-center gap-1.5 transition-colors"
        >
          <ArrowLeft className="w-4 h-4" />
          <span>Back to Main Platform</span>
        </Link>
      </header>

      {/* Main Login Card */}
      <main className="flex-1 flex items-center justify-center px-4 py-12 relative z-10">
        <div className="w-full max-w-md bg-slate-900/90 rounded-3xl border border-slate-800 p-8 sm:p-10 shadow-2xl backdrop-blur-xl space-y-6">
          
          {/* Header */}
          <div className="text-center space-y-2">
            <div className="w-14 h-14 rounded-2xl bg-red-500/10 border border-red-500/30 text-red-500 mx-auto flex items-center justify-center shadow-inner">
              <Lock className="w-7 h-7" />
            </div>
            <h1 className="text-2xl font-black text-white tracking-tight">
              Platform Admin Gateway
            </h1>
            <p className="text-xs text-slate-400 max-w-xs mx-auto">
              Secure moderation hub for credential audits, coach approvals, and GMV transactions.
            </p>
          </div>

          {/* Feedback Messages */}
          {errorMessage && (
            <div className="p-3.5 rounded-2xl bg-rose-500/10 border border-rose-500/30 text-rose-300 text-xs font-medium flex items-start gap-2.5">
              <AlertTriangle className="w-4 h-4 text-rose-400 shrink-0 mt-0.5" />
              <span>{errorMessage}</span>
            </div>
          )}

          {successMessage && (
            <div className="p-3.5 rounded-2xl bg-emerald-500/10 border border-emerald-500/30 text-emerald-300 text-xs font-medium flex items-start gap-2.5">
              <CheckCircle2 className="w-4 h-4 text-emerald-400 shrink-0 mt-0.5" />
              <span>{successMessage}</span>
            </div>
          )}

          {/* Login Form */}
          <form onSubmit={handleAdminLogin} className="space-y-4">
            <div>
              <label className="block text-xs font-bold text-slate-300 uppercase tracking-wider mb-1.5">
                Admin Email ID
              </label>
              <div className="relative">
                <Mail className="w-4 h-4 text-slate-500 absolute left-3.5 top-3.5" />
                <input
                  type="email"
                  required
                  value={adminEmail}
                  onChange={(e) => setAdminEmail(e.target.value)}
                  placeholder="admin@coachconnect.org"
                  className="w-full pl-10 pr-4 py-3 bg-slate-950/70 border border-slate-700/80 rounded-xl text-xs sm:text-sm text-white placeholder:text-slate-500 focus:outline-hidden focus:border-red-500 focus:ring-1 focus:ring-red-500"
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-300 uppercase tracking-wider mb-1.5">
                Secret Access Key / Password
              </label>
              <div className="relative">
                <KeyRound className="w-4 h-4 text-slate-500 absolute left-3.5 top-3.5" />
                <input
                  type={showPassword ? 'text' : 'password'}
                  required
                  value={adminPassword}
                  onChange={(e) => setAdminPassword(e.target.value)}
                  placeholder="••••••••••••"
                  className="w-full pl-10 pr-11 py-3 bg-slate-950/70 border border-slate-700/80 rounded-xl text-xs sm:text-sm text-white placeholder:text-slate-500 focus:outline-hidden focus:border-red-500 focus:ring-1 focus:ring-red-500 font-mono"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3.5 top-3.5 text-slate-500 hover:text-slate-300 cursor-pointer"
                >
                  {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                </button>
              </div>
            </div>

            <div className="pt-2">
              <GlossyPillButton
                type="submit"
                disabled={isLoading}
                className="w-full py-3.5 text-xs font-bold uppercase tracking-wider shadow-lg shadow-red-500/20 flex items-center justify-center gap-2 cursor-pointer"
              >
                <span>{isLoading ? 'Verifying Admin Access...' : 'Authenticate & Enter Hub'}</span>
                {!isLoading && <ArrowRight className="w-4 h-4" />}
              </GlossyPillButton>
            </div>
          </form>

          {/* Quick Demo Credentials Autofill */}
          <div className="pt-2 border-t border-slate-800">
            <button
              type="button"
              onClick={handleAutofill}
              className="w-full p-3 rounded-xl bg-slate-800/60 hover:bg-slate-800 border border-slate-700 text-left transition-colors cursor-pointer group flex items-center justify-between"
            >
              <div className="flex items-center gap-2.5">
                <ShieldCheck className="w-4 h-4 text-amber-400 shrink-0" />
                <div>
                  <div className="text-[11px] font-bold text-slate-200 group-hover:text-amber-400 transition-colors">
                    Default Master Admin Credentials
                  </div>
                  <div className="text-[10px] text-slate-400 font-mono">
                    admin@coachconnect.org • CoachAdmin@2026
                  </div>
                </div>
              </div>
              <span className="text-[10px] font-bold text-amber-400">Fill →</span>
            </button>
          </div>

        </div>
      </main>

      {/* Footer */}
      <footer className="h-16 border-t border-slate-800/80 px-6 flex items-center justify-center text-xs text-slate-500 relative z-10">
        <span>Restricted Area • CoachConnect Security Protocol 2026</span>
      </footer>

    </div>
  );
}

