import React from 'react';
import { useParams, Link } from 'react-router-dom';
import Image from 'next/image';
import { BLOG_POSTS } from 'data/blogData';
import { 
  ArrowLeft, 
  Clock, 
  Calendar, 
  Sparkles, 
  ShieldCheck, 
  ArrowRight
} from 'lucide-react';

export default function BlogPostPage() {
  const { slug } = useParams<{ slug: string }>();
  const post = BLOG_POSTS.find((p) => p.slug === slug);

  if (!post) {
    return (
      <div className="min-h-[60vh] flex flex-col items-center justify-center p-6 text-center">
        <h2 className="text-2xl font-bold text-slate-800 mb-2">Article Not Found</h2>
        <p className="text-slate-500 mb-6">The article you are looking for does not exist or has been moved.</p>
        <Link to="/blog" className="btn-glossy-pill px-6 py-2.5 text-sm">Back to Articles</Link>
      </div>
    );
  }

  const relatedPosts = BLOG_POSTS
    .filter((p) => p.id !== post.id && (p.category === post.category || true))
    .slice(0, 3);

  return (
    <article className="min-h-screen bg-white text-slate-800 pb-20">
      {/* Top Breadcrumb & Navigation */}
      <div className="border-b border-slate-100 bg-slate-50/60">
        <div className="max-w-4xl mx-auto px-4 sm:px-6 py-4 flex items-center justify-between">
          <Link
            to="/blog"
            className="inline-flex items-center gap-2 text-xs font-bold text-slate-600 hover:text-red-600 transition-colors"
          >
            <ArrowLeft className="w-4 h-4" /> Back to All Articles
          </Link>

          <div className="flex items-center gap-2">
            <span className="text-xs font-bold px-3 py-1 rounded-full bg-red-50 text-red-700 border border-red-200">
              {post.category}
            </span>
          </div>
        </div>
      </div>

      {/* Header Container */}
      <header className="max-w-4xl mx-auto px-4 sm:px-6 pt-10 pb-8 space-y-6">
        <div className="flex items-center gap-3 text-xs text-slate-500 font-medium">
          <span className="flex items-center gap-1.5">
            <Clock className="w-3.5 h-3.5 text-slate-400" />
            {post.readTime}
          </span>
          <span>•</span>
          <span className="flex items-center gap-1.5">
            <Calendar className="w-3.5 h-3.5 text-slate-400" />
            {post.publishedAt}
          </span>
        </div>

        <h1 className="text-3xl sm:text-4xl lg:text-5xl font-black text-slate-900 tracking-tight leading-[1.2]">
          {post.title}
        </h1>

        <p className="text-lg text-slate-600 leading-relaxed font-normal">
          {post.excerpt}
        </p>

        {/* Author Metadata Bar */}
        <div className="pt-4 border-t border-slate-100 flex items-center justify-between">
          <div className="flex items-center gap-3.5">
            <img
              src={post.author.avatar}
              alt={post.author.name}
              className="w-12 h-12 rounded-full object-cover border-2 border-red-100 shadow-xs"
            />
            <div>
              <div className="text-sm font-bold text-slate-900 flex items-center gap-1.5">
                {post.author.name}
                <span title="Verified Mentor">
                  <ShieldCheck className="w-4 h-4 text-emerald-500" />
                </span>
              </div>
              <div className="text-xs text-slate-500">{post.author.role}</div>
            </div>
          </div>
        </div>
      </header>

      {/* Main Cover Image */}
      <div className="max-w-5xl mx-auto px-4 sm:px-6 mb-12">
        <div className="relative aspect-[16/9] sm:aspect-[21/9] rounded-3xl overflow-hidden shadow-xl border border-slate-200/80">
          <Image
            src={post.coverImage}
            alt={post.title}
            fill
            priority
            className="object-cover"
          />
        </div>
      </div>

      {/* Article Body Content */}
      <div className="max-w-3xl mx-auto px-4 sm:px-6">
        <div className="prose prose-slate prose-lg max-w-none prose-headings:font-black prose-headings:tracking-tight prose-headings:text-slate-900 prose-p:text-slate-700 prose-p:leading-relaxed prose-li:text-slate-700 prose-strong:text-slate-900">
          {post.content.trim().split('\n\n').map((paragraph, index) => {
            const trimmed = paragraph.trim();
            if (trimmed.startsWith('### ')) {
              return (
                <h3 key={index} className="text-2xl font-bold text-slate-900 mt-10 mb-4">
                  {trimmed.replace('### ', '')}
                </h3>
              );
            }
            if (trimmed.startsWith('1. ') || trimmed.startsWith('2. ') || trimmed.startsWith('3. ') || trimmed.startsWith('4. ')) {
              const lines = trimmed.split('\n');
              return (
                <ol key={index} className="space-y-3 my-6 pl-4">
                  {lines.map((l, liIdx) => (
                    <li key={liIdx} className="text-slate-700 text-base leading-relaxed pl-2">
                      <span dangerouslySetInnerHTML={{ __html: l.replace(/^\d+\.\s+\*\*(.*?)\*\*:\s*/, '<strong>$1:</strong> ') }} />
                    </li>
                  ))}
                </ol>
              );
            }
            return (
              <p key={index} className="text-slate-700 text-base sm:text-lg leading-relaxed mb-6">
                {trimmed}
              </p>
            );
          })}
        </div>

        {/* Tags */}
        <div className="mt-12 pt-6 border-t border-slate-100 flex flex-wrap items-center gap-2">
          <span className="text-xs font-bold text-slate-400 uppercase tracking-wider mr-2">Tags:</span>
          {post.tags.map((tag) => (
            <span
              key={tag}
              className="px-3 py-1 rounded-full bg-slate-100 hover:bg-slate-200 text-xs font-medium text-slate-700 transition-colors"
            >
              #{tag}
            </span>
          ))}
        </div>

        {/* Author Box */}
        <div className="mt-10 p-6 sm:p-8 rounded-3xl bg-slate-50 border border-slate-200/90 flex flex-col sm:flex-row items-start sm:items-center gap-5">
          <img
            src={post.author.avatar}
            alt={post.author.name}
            className="w-16 h-16 rounded-full object-cover border-2 border-white shadow-sm shrink-0"
          />
          <div className="space-y-1.5 flex-1">
            <div className="text-xs font-bold uppercase tracking-wider text-red-600">Article Author</div>
            <h4 className="text-base font-bold text-slate-900">{post.author.name}</h4>
            <p className="text-xs text-slate-600 leading-relaxed">
              {post.author.role}. Verified mentor on CoachConnect specializing in milestone-driven personal and leadership performance.
            </p>
          </div>
          <Link
            to="/coaches"
            className="btn-glossy-pill px-5 py-2.5 text-xs font-bold shrink-0 whitespace-nowrap"
          >
            Book 1:1 Consultation
          </Link>
        </div>

        {/* Category Coach Discovery Callout */}
        <div className="mt-12 bg-gradient-to-r from-red-500 to-rose-600 rounded-3xl p-8 text-white shadow-lg flex flex-col sm:flex-row items-center justify-between gap-6">
          <div className="space-y-2 text-center sm:text-left">
            <div className="inline-flex items-center gap-1.5 text-xs font-bold uppercase tracking-wider bg-white/20 px-3 py-0.5 rounded-full">
              <Sparkles className="w-3 h-3" />
              Ready to take action?
            </div>
            <h3 className="text-2xl font-black">Find a Verified {post.category} Coach</h3>
            <p className="text-xs text-white/90 max-w-md leading-relaxed">
              Browse audited mentors specializing in this exact field. Read verified client reviews, schedule introductory calls, and build your milestone roadmap.
            </p>
          </div>
          <Link
            to={`/coaches?category=${encodeURIComponent(post.category + ' Coach')}`}
            className="bg-white text-slate-900 hover:bg-slate-100 font-bold px-6 py-3 rounded-full text-xs shrink-0 shadow-md transition-all flex items-center gap-2"
          >
            Explore Mentors <ArrowRight className="w-4 h-4 text-red-600" />
          </Link>
        </div>
      </div>

      {/* Related Posts Section */}
      {relatedPosts.length > 0 && (
        <section className="max-w-6xl mx-auto px-4 sm:px-6 mt-20 pt-16 border-t border-slate-100">
          <div className="flex items-center justify-between mb-8">
            <h3 className="text-2xl font-black text-slate-900">Recommended Reading</h3>
            <Link to="/blog" className="text-xs font-bold text-red-600 hover:underline">
              View all articles →
            </Link>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            {relatedPosts.map((related) => (
              <Link
                key={related.id}
                to={`/blog/${related.slug}`}
                className="group block bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-xs hover:shadow-lg transition-all"
              >
                <div className="relative aspect-[16/10] overflow-hidden bg-slate-100">
                  <Image
                    src={related.coverImage}
                    alt={related.title}
                    fill
                    className="object-cover group-hover:scale-105 transition-transform duration-300"
                  />
                  <div className="absolute top-3 left-3 bg-white/90 backdrop-blur-xs text-slate-900 text-[11px] font-bold px-2.5 py-0.5 rounded-full shadow-xs">
                    {related.category}
                  </div>
                </div>
                <div className="p-5 space-y-2">
                  <div className="text-[11px] text-slate-400 font-medium">{related.readTime} • {related.publishedAt}</div>
                  <h4 className="text-base font-bold text-slate-900 group-hover:text-red-600 transition-colors line-clamp-2">
                    {related.title}
                  </h4>
                  <p className="text-xs text-slate-500 line-clamp-2 leading-relaxed">
                    {related.excerpt}
                  </p>
                </div>
              </Link>
            ))}
          </div>
        </section>
      )}
    </article>
  );
}
