import React, { Suspense } from 'react';
import type { Metadata } from 'next';
import BlogListingClient from 'components/BlogListingClient';
import { BLOG_POSTS } from 'data/blogData';

export const metadata: Metadata = {
  title: 'The CoachConnect Journal | Leadership, Health & Mindset Insights',
  description: 'Actionable blueprints, scientific research, and executive strategies written by verified mentors to help you master your craft and life.',
  keywords: [
    'coaching journal',
    'executive coaching blog',
    'leadership articles',
    'metabolic health guides',
    'mindfulness for founders',
    'career progression strategies',
    'mentorship insights'
  ],
  alternates: {
    canonical: '/blog',
  },
  openGraph: {
    title: 'The CoachConnect Journal | Leadership, Health & Mindset',
    description: 'Evidence-backed frameworks and executive perspectives written by verified mentors.',
    url: 'https://coachconnect.org/blog',
    siteName: 'CoachConnect',
    type: 'website',
    images: [
      {
        url: '/og-image.jpg',
        width: 1200,
        height: 630,
        alt: 'The CoachConnect Journal',
      },
    ],
  },
  twitter: {
    card: 'summary_large_image',
    title: 'The CoachConnect Journal | Leadership, Health & Mindset',
    description: 'Evidence-backed frameworks and executive perspectives written by verified mentors.',
    images: ['/og-image.jpg'],
  },
};

export default function BlogPage() {
  const breadcrumbJsonLd = {
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement: [
      {
        '@type': 'ListItem',
        position: 1,
        name: 'Home',
        item: 'https://coachconnect.org',
      },
      {
        '@type': 'ListItem',
        position: 2,
        name: 'Journal',
        item: 'https://coachconnect.org/blog',
      },
    ],
  };

  const blogJsonLd = {
    '@context': 'https://schema.org',
    '@type': 'Blog',
    name: 'The CoachConnect Journal',
    description: 'Actionable blueprints, scientific research, and executive strategies written by verified mentors.',
    url: 'https://coachconnect.org/blog',
    blogPost: BLOG_POSTS.map((post) => ({
      '@type': 'BlogPosting',
      headline: post.title,
      description: post.excerpt,
      url: `https://coachconnect.org/blog/${post.slug}`,
      datePublished: post.publishedAt,
      author: {
        '@type': 'Person',
        name: post.author.name,
      },
    })),
  };

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumbJsonLd) }}
      />
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(blogJsonLd) }}
      />
      <Suspense fallback={<div className="p-12 text-center text-slate-500">Loading articles...</div>}>
        <BlogListingClient />
      </Suspense>
    </>
  );
}
