import { createClient } from 'utils/supabase/client';

export interface UploadResult {
  url: string;
  path: string;
  error?: string;
  isFallback?: boolean;
  sizeBytes?: number;
  fileName: string;
}

/**
 * Compresses an image file client-side using HTML5 Canvas to keep file sizes
 * lightweight (~40KB-150KB) while maintaining crisp visual fidelity.
 * Prevents localStorage quota overflow and speeds up network uploads.
 */
export async function compressImage(
  file: File,
  maxWidth = 800,
  maxHeight = 800,
  quality = 0.85
): Promise<{ file: File; dataUrl: string }> {
  // If not an image or in SSR, fallback directly
  if (typeof window === 'undefined' || !file.type.startsWith('image/')) {
    const dataUrl = await fileToDataUrl(file);
    return { file, dataUrl };
  }

  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        let width = img.width;
        let height = img.height;

        if (width > height) {
          if (width > maxWidth) {
            height = Math.round((height * maxWidth) / width);
            width = maxWidth;
          }
        } else {
          if (height > maxHeight) {
            width = Math.round((width * maxHeight) / height);
            height = maxHeight;
          }
        }

        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');

        if (!ctx) {
          fileToDataUrl(file).then((fallbackUrl) => resolve({ file, dataUrl: fallbackUrl }));
          return;
        }

        ctx.drawImage(img, 0, 0, width, height);

        const mimeType = file.type === 'image/png' ? 'image/png' : 'image/jpeg';
        const dataUrl = canvas.toDataURL(mimeType, quality);

        canvas.toBlob(
          (blob) => {
            if (blob) {
              const compressedFile = new File([blob], file.name, {
                type: mimeType,
                lastModified: Date.now()
              });
              resolve({ file: compressedFile, dataUrl });
            } else {
              resolve({ file, dataUrl });
            }
          },
          mimeType,
          quality
        );
      };

      img.onerror = () => {
        fileToDataUrl(file).then((fallbackUrl) => resolve({ file, dataUrl: fallbackUrl }));
      };

      img.src = e.target?.result as string;
    };

    reader.onerror = () => {
      fileToDataUrl(file).then((fallbackUrl) => resolve({ file, dataUrl: fallbackUrl }));
    };

    reader.readAsDataURL(file);
  });
}

/**
 * Uploads a file (photo or certificate document) to Supabase Storage bucket 'coach-assets'.
 * Automatically optimizes images and uses resilient client-side storage fallback if
 * Supabase storage bucket is not configured or blocked.
 */
export async function uploadToSupabaseStorage(
  rawFile: File,
  folder: 'avatars' | 'certificates' | 'covers' | 'audio' | 'videos' | 'ebooks' = 'avatars'
): Promise<UploadResult> {
  const isImage = rawFile.type.startsWith('image/');
  const isVideo = folder === 'videos' || rawFile.type.startsWith('video/');
  let fileToUpload = rawFile;
  let compressedDataUrl = '';

  if (isImage) {
    try {
      const compressed = await compressImage(rawFile, 800, 800, 0.85);
      fileToUpload = compressed.file;
      compressedDataUrl = compressed.dataUrl;
    } catch {
      compressedDataUrl = await fileToDataUrl(rawFile);
    }
  } else {
    if (!isVideo || rawFile.size < 15 * 1024 * 1024) {
      compressedDataUrl = await fileToDataUrl(rawFile);
    }
  }

  const isAudio = folder === 'audio' || rawFile.type.startsWith('audio/');
  const fileExt = fileToUpload.name.split('.').pop() || (isVideo ? 'mp4' : isAudio ? 'webm' : isImage ? 'jpg' : 'pdf');
  const safeBaseName = fileToUpload.name.replace(/[^a-zA-Z0-9.-]/g, '_').substring(0, 30);
  const fileName = `${folder}/${Date.now()}-${safeBaseName}`;

  try {
    const supabase = createClient();
    const contentType = rawFile.type || (isVideo ? 'video/mp4' : isAudio ? 'audio/webm' : isImage ? 'image/jpeg' : 'application/pdf');
    const { data, error } = await supabase.storage
      .from('coach-assets')
      .upload(fileName, fileToUpload, {
        cacheControl: '3600',
        contentType,
        upsert: true
      });

    if (error) {
      console.warn('Supabase storage upload fallback:', error.message);
      return {
        url: compressedDataUrl,
        path: fileName,
        fileName: rawFile.name,
        sizeBytes: fileToUpload.size,
        error: error.message,
        isFallback: true
      };
    }

    const { data: publicUrlData } = supabase.storage
      .from('coach-assets')
      .getPublicUrl(data.path);

    return {
      url: publicUrlData.publicUrl,
      path: data.path,
      fileName: rawFile.name,
      sizeBytes: fileToUpload.size,
      isFallback: false
    };
  } catch (err: any) {
    console.warn('Supabase storage upload error:', err.message);
    return {
      url: compressedDataUrl,
      path: fileName,
      fileName: rawFile.name,
      sizeBytes: fileToUpload.size,
      error: err.message,
      isFallback: true
    };
  }
}

export function fileToDataUrl(file: File): Promise<string> {
  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve((reader.result as string) || '');
    reader.onerror = () => resolve('');
    reader.readAsDataURL(file);
  });
}
