// lib/taxEngine.ts
// International tax rules, calculation, and invoice formatting engine

export interface TaxRule {
  countryCode: string;
  countryName: string;
  rate: number; // e.g. 0.18 = 18%
  taxName: string; // "GST", "VAT", "Sales Tax"
  breakdownLabel?: string;
  isReverseChargeApplicable?: boolean;
}

export const COUNTRY_TAX_RULES: Record<string, TaxRule> = {
  IN: {
    countryCode: 'IN',
    countryName: 'India',
    rate: 0.18,
    taxName: 'GST (18%)',
    breakdownLabel: 'CGST (9%) + SGST (9%) / IGST (18%)'
  },
  GB: {
    countryCode: 'GB',
    countryName: 'United Kingdom',
    rate: 0.20,
    taxName: 'UK VAT (20%)',
    breakdownLabel: 'Standard Rate Value Added Tax'
  },
  EU: {
    countryCode: 'EU',
    countryName: 'European Union',
    rate: 0.20,
    taxName: 'EU VAT (20%)',
    breakdownLabel: 'EU Digital Services VAT'
  },
  AE: {
    countryCode: 'AE',
    countryName: 'United Arab Emirates',
    rate: 0.05,
    taxName: 'UAE VAT (5%)',
    breakdownLabel: 'Federal Tax Authority VAT'
  },
  US: {
    countryCode: 'US',
    countryName: 'United States',
    rate: 0.0,
    taxName: 'State Tax Exempt',
    breakdownLabel: 'Cross-Border Digital Service'
  },
  AU: {
    countryCode: 'AU',
    countryName: 'Australia',
    rate: 0.10,
    taxName: 'GST (10%)',
    breakdownLabel: 'Australian Goods & Services Tax'
  },
  CA: {
    countryCode: 'CA',
    countryName: 'Canada',
    rate: 0.05,
    taxName: 'GST (5%)',
    breakdownLabel: 'Canada Federal GST'
  },
  SG: {
    countryCode: 'SG',
    countryName: 'Singapore',
    rate: 0.09,
    taxName: 'GST (9%)',
    breakdownLabel: 'IRAS Goods & Services Tax'
  }
};

/**
 * Calculates tax breakdown based on country code and subtotal.
 */
export function calculateTax(amount: number, countryCode: string = 'IN') {
  const code = countryCode.toUpperCase();
  const rule = COUNTRY_TAX_RULES[code] || COUNTRY_TAX_RULES.IN;

  const taxAmount = Math.round(amount * rule.rate * 100) / 100;
  const total = Math.round((amount + taxAmount) * 100) / 100;

  return {
    subtotal: amount,
    taxRate: rule.rate,
    taxRatePercentage: `${Math.round(rule.rate * 100)}%`,
    taxName: rule.taxName,
    breakdownLabel: rule.breakdownLabel || rule.taxName,
    taxAmount,
    total
  };
}

