'use client';

import React from 'react';
import { cn } from 'lib/utils';

interface GlossyPillButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  children: React.ReactNode;
  variant?: 'primary' | 'secondary';
  className?: string;
}

export function GlossyPillButton({
  children,
  variant = 'primary',
  className,
  style,
  ...props
}: GlossyPillButtonProps) {
  const isPrimary = variant === 'primary';

  const primaryStyle: React.CSSProperties = {
    background: 'linear-gradient(180deg, #f03a3a 0%, #dc2626 50%, #b91c1c 100%)',
    border: '1px solid rgba(255, 140, 140, 0.55)',
    boxShadow:
      '0 10px 24px -3px rgba(220, 38, 38, 0.45), 0 4px 8px -2px rgba(220, 38, 38, 0.25), inset 0 1.5px 1.5px 0 rgba(255, 255, 255, 0.75), inset 0 -2px 4px 0 rgba(0, 0, 0, 0.22)',
    textShadow: '0 1px 2px rgba(0, 0, 0, 0.25)',
    color: '#ffffff',
    ...style,
  };

  const secondaryStyle: React.CSSProperties = {
    background: 'linear-gradient(180deg, #ffffff 0%, #f8fafc 100%)',
    border: '1px solid rgba(226, 232, 240, 0.9)',
    boxShadow: '0 4px 12px -2px rgba(0, 0, 0, 0.06), inset 0 1px 1.5px 0 rgba(255, 255, 255, 1)',
    color: '#1e293b',
    ...style,
  };

  return (
    <button
      {...props}
      style={isPrimary ? primaryStyle : secondaryStyle}
      className={cn(
        'relative inline-flex items-center justify-center font-bold rounded-full select-none cursor-pointer transition-all duration-200 active:scale-95 active:translate-y-[1px]',
        isPrimary ? 'hover:brightness-105 hover:-translate-y-0.5' : 'hover:bg-slate-50 hover:-translate-y-0.5',
        className
      )}
    >
      {children}
    </button>
  );
}

export default GlossyPillButton;
