import { Country, State, City } from 'country-state-city';
import type { ICountry, IState, ICity } from 'country-state-city';

export interface LocationCountry {
  name: string;
  isoCode: string;
  flag: string;
  badge: string;
  phonecode: string;
  phoneCode?: string;
  currency: string;
  currencySymbol: string;
}

export interface LocationState {
  name: string;
  isoCode: string;
  countryCode: string;
}

export interface LocationCity {
  name: string;
  stateCode?: string;
  countryCode: string;
}

// Popular international currencies mapping with symbols
export const POPULAR_CURRENCIES: Record<string, { symbol: string; name: string; flag: string; badge: string }> = {
  INR: { symbol: '₹', name: 'Indian Rupee', flag: 'IN', badge: 'IN' },
  USD: { symbol: '$', name: 'US Dollar', flag: 'US', badge: 'US' },
  EUR: { symbol: '€', name: 'Euro', flag: 'EU', badge: 'EU' },
  GBP: { symbol: '£', name: 'British Pound', flag: 'GB', badge: 'GB' },
  AED: { symbol: 'AED', name: 'UAE Dirham', flag: 'AE', badge: 'AE' },
  AUD: { symbol: 'A$', name: 'Australian Dollar', flag: 'AU', badge: 'AU' },
  CAD: { symbol: 'C$', name: 'Canadian Dollar', flag: 'CA', badge: 'CA' },
  SGD: { symbol: 'S$', name: 'Singapore Dollar', flag: 'SG', badge: 'SG' },
};

// Common timezones with offsets
export const POPULAR_TIMEZONES = [
  { value: 'IST (UTC+5:30)', label: 'IST (UTC+5:30) - India Standard Time', country: 'IN' },
  { value: 'EST (UTC-5)', label: 'EST (UTC-5) - Eastern Standard Time (US/CA)', country: 'US' },
  { value: 'CST (UTC-6)', label: 'CST (UTC-6) - Central Standard Time (US/CA)', country: 'US' },
  { value: 'PST (UTC-8)', label: 'PST (UTC-8) - Pacific Standard Time (US/CA)', country: 'US' },
  { value: 'GMT (UTC+0)', label: 'GMT (UTC+0) - Greenwich Mean Time (UK)', country: 'GB' },
  { value: 'CET (UTC+1)', label: 'CET (UTC+1) - Central European Time', country: 'DE' },
  { value: 'GST (UTC+4)', label: 'GST (UTC+4) - Gulf Standard Time (Dubai/UAE)', country: 'AE' },
  { value: 'SGT (UTC+8)', label: 'SGT (UTC+8) - Singapore / HK Time', country: 'SG' },
  { value: 'AEST (UTC+10)', label: 'AEST (UTC+10) - Australian Eastern Time', country: 'AU' },
  { value: 'NZST (UTC+12)', label: 'NZST (UTC+12) - New Zealand Time', country: 'NZ' },
];

/**
 * Get currency symbol for a currency code
 */
export function getCurrencySymbol(currencyCode: string): string {
  const code = (currencyCode || '').toUpperCase().trim();
  if (POPULAR_CURRENCIES[code]) {
    return POPULAR_CURRENCIES[code].symbol;
  }
  if (code === 'INR') return '₹';
  if (code === 'USD') return '$';
  if (code === 'EUR') return '€';
  if (code === 'GBP') return '£';
  if (code === 'AED') return 'AED';
  if (code === 'AUD') return 'A$';
  if (code === 'CAD') return 'C$';
  return code || '$';
}

/**
 * Get all countries with currency symbols and phone codes
 */
export function getAllCountries(): LocationCountry[] {
  return Country.getAllCountries().map((c: ICountry) => {
    const rawPhone = c.phonecode.startsWith('+') ? c.phonecode : `+${c.phonecode}`;
    return {
      name: c.name,
      isoCode: c.isoCode,
      flag: c.isoCode, // Clean 2-letter uppercase badge
      badge: c.isoCode,
      phonecode: rawPhone,
      phoneCode: rawPhone,
      currency: c.currency,
      currencySymbol: getCurrencySymbol(c.currency),
    };
  });
}

/**
 * Get states of a country
 */
export function getStatesOfCountry(countryCode: string): LocationState[] {
  if (!countryCode) return [];
  return State.getStatesOfCountry(countryCode).map((s: IState) => ({
    name: s.name,
    isoCode: s.isoCode,
    countryCode: s.countryCode,
  }));
}

/**
 * Get cities of a state
 */
export function getCitiesOfState(countryCode: string, stateCode?: string): LocationCity[] {
  if (!countryCode) return [];
  if (stateCode) {
    return (City.getCitiesOfState(countryCode, stateCode) || []).map((c: ICity) => ({
      name: c.name,
      stateCode: c.stateCode,
      countryCode: c.countryCode,
    }));
  }
  return (City.getCitiesOfCountry(countryCode) || []).map((c: ICity) => ({
    name: c.name,
    stateCode: c.stateCode,
    countryCode: c.countryCode,
  }));
}

/**
 * Find country info by ISO code or Name
 */
export function findCountry(query: string): LocationCountry | null {
  if (!query) return null;
  const q = query.trim().toLowerCase();
  const all = getAllCountries();
  return (
    all.find((c) => c.isoCode.toLowerCase() === q || c.name.toLowerCase() === q) || null
  );
}
