'use client';

import React, { useState, useEffect, useRef } from 'react';
import Image from 'next/image';
import { useApp } from 'context/AppContext';
import { Coach } from 'data/coachesData';
import { 
  X, 
  Send, 
  MessageSquare, 
  ShieldCheck, 
  Sparkles, 
  Video, 
  Calendar, 
  CheckCheck, 
  Check,
  Lock,
  Paperclip,
  Search,
  FileText,
  Image as ImageIcon,
  Clock,
  User,
  ArrowRight
} from 'lucide-react';
import AuthModal from 'components/AuthModal';

interface CoachChatModalProps {
  coach: Coach;
  isOpen: boolean;
  onClose: () => void;
  onOpenBooking: () => void;
}

export default function CoachChatModal({ coach, isOpen, onClose, onOpenBooking }: CoachChatModalProps) {
  const { chatMessages, sendChatMessage, bookings, currentUser, markConversationAsRead } = useApp();
  const [inputText, setInputText] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [authModalOpen, setAuthModalOpen] = useState(false);
  const [attachment, setAttachment] = useState<{ url: string; name: string; type?: 'image' | 'file' } | null>(null);
  
  const fileInputRef = useRef<HTMLInputElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Check if client has confirmed booked session with this coach
  const isBooked = bookings.some(
    (b) => b.coachId === coach.id && b.status !== 'cancelled'
  );

  // Filter messages for this coach
  const coachMessages = chatMessages.filter((m) => m.coachId === coach.id);

  const displayedMessages = searchQuery.trim()
    ? coachMessages.filter((m) => m.text.toLowerCase().includes(searchQuery.toLowerCase()))
    : coachMessages;

  // Mark conversation as read on modal open
  useEffect(() => {
    if (isOpen) {
      markConversationAsRead(coach.id);
    }
  }, [isOpen, coach.id, markConversationAsRead]);

  // Auto-scroll to bottom
  useEffect(() => {
    if (isOpen) {
      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [coachMessages, isOpen, isTyping]);

  if (!isOpen) return null;

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const isImg = file.type.startsWith('image/');
    const reader = new FileReader();
    reader.onload = () => {
      setAttachment({
        url: reader.result as string,
        name: file.name,
        type: isImg ? 'image' : 'file',
      });
    };
    reader.readAsDataURL(file);
  };

  const handleSendMessage = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!currentUser) {
      setAuthModalOpen(true);
      return;
    }
    if (!inputText.trim() && !attachment) return;

    sendChatMessage(
      coach.id, 
      inputText.trim() || (attachment ? `Shared attachment: ${attachment.name}` : ''), 
      'user',
      attachment || undefined
    );

    setInputText('');
    setAttachment(null);
    setIsTyping(true);

    setTimeout(() => {
      setIsTyping(false);
    }, 1400);
  };

  const handleQuickPrompt = (prompt: string) => {
    if (!currentUser) {
      setAuthModalOpen(true);
      return;
    }
    sendChatMessage(coach.id, prompt, 'user');
    setIsTyping(true);
    setTimeout(() => {
      setIsTyping(false);
    }, 1400);
  };

  return (
    <>
      <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-slate-900/30 backdrop-blur-xs animate-in fade-in">
        <div className="bg-white rounded-3xl max-w-xl w-full h-[620px] max-h-[92vh] shadow-[0_25px_60px_-15px_rgba(0,0,0,0.18)] border border-slate-200/90 flex flex-col overflow-hidden relative">
          
          {/* Light Sleek Chat Header */}
          <div className="bg-white px-5 py-3.5 flex items-center justify-between border-b border-slate-100 shrink-0">
            <div className="flex items-center gap-3">
              <div className="relative">
                <div className="w-10 h-10 sm:w-11 sm:h-11 rounded-2xl overflow-hidden border border-slate-200 bg-slate-100 shadow-2xs">
                  <Image
                    src={coach.photoUrl}
                    alt={coach.name}
                    width={44}
                    height={44}
                    unoptimized={Boolean(coach.photoUrl?.startsWith('data:'))}
                    className="object-cover w-full h-full"
                  />
                </div>
                <span className="absolute -bottom-0.5 -right-0.5 w-3 h-3 rounded-full bg-emerald-500 border-2 border-white" />
              </div>

              <div>
                <div className="flex items-center gap-1.5">
                  <h3 className="font-bold text-sm sm:text-base text-slate-900">{coach.name}</h3>
                  <ShieldCheck className="w-4 h-4 text-emerald-600" />
                </div>
                <div className="flex items-center gap-2 text-xs text-slate-500">
                  <span className="text-red-600 font-bold">{coach.primaryCategory}</span>
                  <span>•</span>
                  <span className="flex items-center gap-1 text-emerald-700 font-medium">
                    <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                    Available Now
                  </span>
                </div>
              </div>
            </div>

            <div className="flex items-center gap-1.5">
              <button
                type="button"
                onClick={() => setIsSearchOpen(!isSearchOpen)}
                className="p-2 rounded-full text-slate-400 hover:text-slate-700 hover:bg-slate-100 transition-colors cursor-pointer"
                title="Search conversation"
              >
                <Search className="w-4 h-4" />
              </button>

              <button
                type="button"
                onClick={() => {
                  onClose();
                  onOpenBooking();
                }}
                className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-red-600 hover:bg-red-700 text-white text-xs font-bold transition-all shadow-xs cursor-pointer"
              >
                <Calendar className="w-3.5 h-3.5" /> 
                <span className="hidden sm:inline">Book Session</span>
                <span className="sm:hidden">Book</span>
              </button>

              <button
                onClick={onClose}
                className="p-2 rounded-full text-slate-400 hover:text-slate-700 hover:bg-slate-100 transition-colors cursor-pointer"
              >
                <X className="w-5 h-5" />
              </button>
            </div>
          </div>

          {/* Search Bar Toggle */}
          {isSearchOpen && (
            <div className="px-4 py-2 bg-slate-50 border-b border-slate-200 flex items-center gap-2">
              <Search className="w-3.5 h-3.5 text-slate-400 shrink-0" />
              <input
                type="text"
                autoFocus
                placeholder="Filter messages in this conversation..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full text-xs bg-transparent focus:outline-hidden text-slate-800"
              />
              {searchQuery && (
                <button
                  type="button"
                  onClick={() => setSearchQuery('')}
                  className="text-slate-400 hover:text-slate-600 text-xs font-bold cursor-pointer"
                >
                  Clear
                </button>
              )}
            </div>
          )}

          {/* Status Indicator Strip */}
          <div className="bg-slate-50/90 border-b border-slate-100 px-4 py-1.5 flex items-center justify-between text-xs text-slate-700">
            <span className="flex items-center gap-1.5 font-semibold text-slate-700 text-[11px]">
              <Sparkles className="w-3.5 h-3.5 text-red-500" />
              Direct 1:1 conversation with {coach.name}
            </span>
            <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full border ${
              isBooked 
                ? 'bg-emerald-50 text-emerald-700 border-emerald-200' 
                : 'bg-white text-slate-600 border-slate-200'
            }`}>
              {isBooked ? 'Confirmed Client Channel' : 'Pre-Session Inquiry'}
            </span>
          </div>

          {/* Chat Messages Body */}
          <div className="flex-1 p-4 sm:p-5 overflow-y-auto space-y-3 bg-slate-50/40">
            
            {/* If NOT signed in, show sleek light banner to sign in */}
            {!currentUser && (
              <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-xs text-center space-y-2 mb-3">
                <div className="w-9 h-9 rounded-xl bg-red-50 text-red-600 mx-auto flex items-center justify-center">
                  <User className="w-5 h-5" />
                </div>
                <h4 className="text-xs sm:text-sm font-bold text-slate-900">Sign in to start messaging {coach.name}</h4>
                <p className="text-[11px] text-slate-500 max-w-xs mx-auto">
                  Instant sign in with 6-digit Email OTP. Send questions and schedule strategy calls.
                </p>
                <button
                  type="button"
                  onClick={() => setAuthModalOpen(true)}
                  className="btn-glossy-pill px-4 py-1.5 text-xs font-bold shadow-xs cursor-pointer inline-flex items-center gap-1.5"
                >
                  <span>Sign In with OTP</span>
                  <ArrowRight className="w-3.5 h-3.5" />
                </button>
              </div>
            )}

            {displayedMessages.length === 0 ? (
              <div className="text-center py-8 px-4 space-y-3">
                <div className="w-12 h-12 rounded-2xl bg-red-50 text-red-600 mx-auto flex items-center justify-center border border-red-100">
                  <MessageSquare className="w-6 h-6" />
                </div>
                <h4 className="font-bold text-slate-900 text-sm">Direct Messaging with {coach.name}</h4>
                <p className="text-xs text-slate-500 max-w-sm mx-auto leading-relaxed">
                  Ask about session preparation, coaching methodology, or share your goals. Replies typically arrive within a few hours.
                </p>
              </div>
            ) : (
              displayedMessages.map((msg) => {
                const isMe = msg.sender === 'user';
                return (
                  <div
                    key={msg.id}
                    className={`flex items-end gap-2 ${isMe ? 'justify-end' : 'justify-start'}`}
                  >
                    {!isMe && (
                      <img
                        src={coach.photoUrl}
                        alt={coach.name}
                        className="w-7 h-7 rounded-full object-cover border border-slate-200 mb-1 shrink-0"
                      />
                    )}

                    <div className={`max-w-[80%] space-y-1 ${isMe ? 'items-end' : 'items-start'}`}>
                      <div
                        className={`p-3 sm:p-3.5 rounded-2xl text-xs sm:text-sm leading-relaxed shadow-xs ${
                          isMe
                            ? 'bg-[#E02B20] text-white rounded-br-xs'
                            : 'bg-white text-slate-800 border border-slate-200/90 rounded-bl-xs'
                        }`}
                      >
                        <div>{msg.text}</div>

                        {/* Attachment render */}
                        {msg.attachmentUrl && (
                          <div className="mt-2 pt-2 border-t border-white/20">
                            {msg.attachmentType === 'image' ? (
                              <img
                                src={msg.attachmentUrl}
                                alt={msg.attachmentName || 'Attachment'}
                                className="rounded-xl max-h-48 object-cover border border-white/20"
                              />
                            ) : (
                              <div className={`flex items-center gap-2 p-2 rounded-lg text-xs font-semibold ${isMe ? 'bg-white/10 text-white' : 'bg-slate-100 text-slate-800'}`}>
                                <FileText className="w-4 h-4 shrink-0" />
                                <span className="truncate">{msg.attachmentName || 'Attached Document'}</span>
                              </div>
                            )}
                          </div>
                        )}
                      </div>

                      <div className={`flex items-center gap-1 text-[10px] text-slate-400 px-1 ${isMe ? 'justify-end' : 'justify-start'}`}>
                        <span>{msg.timestamp}</span>
                        {isMe && (
                          msg.status === 'read' ? (
                            <span title="Read"><CheckCheck className="w-3.5 h-3.5 text-blue-500" /></span>
                          ) : msg.status === 'delivered' ? (
                            <span title="Delivered"><CheckCheck className="w-3.5 h-3.5 text-slate-400" /></span>
                          ) : (
                            <span title="Sent"><Check className="w-3 h-3 text-slate-400" /></span>
                          )
                        )}
                      </div>
                    </div>
                  </div>
                );
              })
            )}

            {/* Typing Indicator */}
            {isTyping && (
              <div className="flex items-center gap-2 text-xs text-slate-500 animate-in fade-in">
                <img
                  src={coach.photoUrl}
                  alt={coach.name}
                  className="w-6 h-6 rounded-full object-cover shrink-0"
                />
                <div className="bg-white px-3 py-2 rounded-2xl border border-slate-200 shadow-2xs flex items-center gap-1.5">
                  <span className="w-1.5 h-1.5 rounded-full bg-slate-400 animate-bounce" />
                  <span className="w-1.5 h-1.5 rounded-full bg-slate-400 animate-bounce [animation-delay:0.2s]" />
                  <span className="w-1.5 h-1.5 rounded-full bg-slate-400 animate-bounce [animation-delay:0.4s]" />
                </div>
              </div>
            )}

            <div ref={messagesEndRef} />
          </div>

          {/* Quick Suggestion Prompt Pills */}
          <div className="px-4 py-2 bg-white border-t border-slate-100 flex items-center gap-2 overflow-x-auto scrollbar-none shrink-0">
            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider shrink-0">Suggestions:</span>
            {[
              'What should I prepare before our session?',
              'Do you offer customized packages?',
              'Can I share my current career roadmap?',
              'Looking forward to our scheduled call!'
            ].map((prompt, idx) => (
              <button
                key={idx}
                type="button"
                onClick={() => handleQuickPrompt(prompt)}
                className="text-xs bg-slate-50 hover:bg-red-50 hover:text-red-600 text-slate-600 px-2.5 py-1 rounded-full whitespace-nowrap transition-colors border border-slate-200/80 cursor-pointer"
              >
                {prompt}
              </button>
            ))}
          </div>

          {/* Attachment preview banner */}
          {attachment && (
            <div className="px-4 py-2 bg-slate-50 border-t border-slate-200 flex items-center justify-between text-xs text-slate-800 shrink-0">
              <div className="flex items-center gap-2 truncate">
                {attachment.type === 'image' ? <ImageIcon className="w-4 h-4 text-red-500" /> : <FileText className="w-4 h-4 text-red-500" />}
                <span className="font-semibold truncate">Attachment: {attachment.name}</span>
              </div>
              <button
                type="button"
                onClick={() => setAttachment(null)}
                className="text-slate-500 hover:text-slate-800 font-bold p-1 cursor-pointer"
              >
                <X className="w-3.5 h-3.5" />
              </button>
            </div>
          )}

          {/* Message Input Form */}
          <form onSubmit={handleSendMessage} className="p-3 bg-white border-t border-slate-200 flex items-center gap-2 shrink-0">
            <input
              type="file"
              ref={fileInputRef}
              onChange={handleFileUpload}
              accept="image/*,.pdf,.doc,.docx,.txt"
              className="hidden"
            />

            <button
              type="button"
              onClick={() => fileInputRef.current?.click()}
              className="p-2.5 rounded-full text-slate-400 hover:text-slate-700 hover:bg-slate-100 transition-colors cursor-pointer shrink-0"
              title="Attach Document or Image"
            >
              <Paperclip className="w-4 h-4" />
            </button>

            <input
              type="text"
              placeholder={`Message ${coach.name}...`}
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              className="flex-1 px-4 py-2 rounded-full bg-slate-100/90 border border-slate-200 focus:bg-white focus:border-red-400 focus:outline-hidden text-xs sm:text-sm font-medium transition-all"
            />

            <button
              type="submit"
              className="btn-glossy-pill w-9 h-9 rounded-full flex items-center justify-center text-white shrink-0 shadow-xs cursor-pointer"
              title="Send Message"
            >
              <Send className="w-3.5 h-3.5 ml-0.5" />
            </button>
          </form>

        </div>
      </div>

      {authModalOpen && (
        <AuthModal
          isOpen={authModalOpen}
          onClose={() => setAuthModalOpen(false)}
          initialMode="signin"
        />
      )}
    </>
  );
}