const { useNavigate, useLocation, useParams, useSearchParams } = require('react-router-dom');

function useRouter() {
  const navigate = useNavigate();
  return {
    push: function (url) { navigate(url); },
    replace: function (url) { navigate(url, { replace: true }); },
    back: function () { navigate(-1); },
    forward: function () { window.history.forward(); },
    refresh: function () { window.location.reload(); },
    prefetch: function () {},
  };
}

function usePathname() {
  const location = useLocation();
  return location.pathname;
}

function useNextSearchParams() {
  const [searchParams] = useSearchParams();
  return searchParams;
}

function notFound() {
  console.warn('Page not found');
}

module.exports = {
  useRouter,
  usePathname,
  useSearchParams: useNextSearchParams,
  useParams,
  notFound,
};
