'use client';

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Coach, INITIAL_COACHES, EducationItem, CertificationItem, AwardItem, ServicePackage, CoachEbook, Review } from 'data/coachesData';
import { syncApplicationWithSupabase, syncCoachApprovalWithSupabase } from 'lib/supabaseSync';
import { createClient } from 'utils/supabase/client';
import { generateDeterministicZoomMeeting } from 'lib/zoomMeeting';
import { getTranslation } from 'lib/i18n';
import { apiClient } from 'lib/apiClient';
import { 
  fetchCoachesFromSupabase, 
  fetchApplicationsFromSupabase, 
  fetchBookingsFromSupabase, 
  fetchInquiriesFromSupabase,
  insertBookingToSupabase,
  insertInquiryToSupabase,
  insertApplicationToSupabase,
  insertCoachToSupabase,
  upsertProfileToSupabase,
  deleteCoachFromSupabase,
  deleteApplicationFromSupabase,
  deleteBookingFromSupabase,
  deleteInquiryFromSupabase
} from 'lib/supabaseDb';

export type UserRole = 'visitor' | 'client' | 'coach' | 'admin';

