  const sendChatMessage = (
    coachId: string, 
    text: string, 
    senderOverride?: 'user' | 'coach',
    attachment?: { url: string; name: string; type?: 'image' | 'file' }
  ) => {
    const targetCoach = coaches.find((c) => c.id === coachId || c.slug === coachId) || coaches[0];
    const isFromCoach = senderOverride === 'coach';
    const sender = senderOverride || 'user';
    const now = new Date();
    const timeStr = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

    const newMsg: ChatMessage = {
      id: `chat-${Date.now()}-${Math.random().toString(36).substr(2, 4)}`,
      coachId: targetCoach.id,
      coachName: targetCoach.name,
      coachAvatar: targetCoach.photoUrl,
      userId: currentUser?.id || 'usr-client',
      userName: currentUser?.fullName || 'Client',
      userAvatar: currentUser?.avatarUrl,
      sender,
      text,
      timestamp: `Today, ${timeStr}`,
      read: true,
      status: 'delivered',
      attachmentUrl: attachment?.url,
      attachmentName: attachment?.name,
      attachmentType: attachment?.type || 'file'
    };

    setChatMessages((prev) => {
      const updated = [...prev, newMsg];
      try {
        localStorage.setItem('coachconnect_chat_messages', JSON.stringify(updated));
      } catch {}
      return updated;
    });

    // If user sent the message, simulate coach reply after 1.2s delay
    if (!isFromCoach) {
      setTimeout(() => {
        let replyText = `Thanks for reaching out! I would love to help you achieve your goals. Feel free to book a 1:1 strategy Zoom call using the booking button, or let me know what questions you have.`;
        const lower = text.toLowerCase();
        if (lower.includes('price') || lower.includes('fee') || lower.includes('cost') || lower.includes('charge')) {
          replyText = `My sessions start at ${targetCoach.currency}${targetCoach.startingPrice.toLocaleString()}. All packages include 1:1 video consultation over Zoom, personalized action blueprints, and follow-up support!`;
        } else if (lower.includes('zoom') || lower.includes('call') || lower.includes('meet') || lower.includes('time') || lower.includes('slot') || lower.includes('schedule')) {
          replyText = `Yes! All sessions are conducted via secure HD Zoom video meetings. You can pick an instant slot from my calendar right on this page, and a Zoom link with Meeting ID & Passcode will be generated immediately for you.`;
        } else if (lower.includes('method') || lower.includes('approach') || lower.includes('how')) {
          replyText = `My coaching philosophy is: "${targetCoach.coachingPhilosophy}". We break down overwhelming goals into weekly milestone sprints with direct accountability.`;
        } else if (lower.includes('hello') || lower.includes('hi') || lower.includes('hey')) {
          replyText = `Hello! Great to connect with you. I specialize in ${targetCoach.specialties.slice(0, 2).join(' & ')}. What specific milestone are you looking to focus on right now?`;
        }

        const coachReply: ChatMessage = {
          id: `chat-${Date.now() + 1}`,
          coachId: targetCoach.id,
          coachName: targetCoach.name,
          coachAvatar: targetCoach.photoUrl,
          userId: currentUser?.id || 'usr-client',
          userName: currentUser?.fullName || 'Client',
          userAvatar: currentUser?.avatarUrl,
          sender: 'coach',
          text: replyText,
          timestamp: `Today, ${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`,
          read: true,
          status: 'read'
        };

        setChatMessages((prev) => {
          const updated = [...prev, coachReply];
          try {
            localStorage.setItem('coachconnect_chat_messages', JSON.stringify(updated));
          } catch {}
          return updated;
        });
      }, 1200);
    }
  };

