  const addCoachReview = (coachId: string, reviewData: Omit<Review, 'id' | 'date'> & { date?: string }): Review => {
    const newReview: Review = {
      id: `rev-${Date.now()}-${Math.random().toString(36).substr(2, 4)}`,
      clientName: reviewData.clientName || 'Verified Client',
      clientAvatar: reviewData.clientAvatar || 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=200&q=80',
      rating: reviewData.rating || 5,
      date: reviewData.date || 'Just now',
      sessionType: reviewData.sessionType || '1:1 Coaching',
      comment: reviewData.comment || '',
      coachResponse: reviewData.coachResponse
    };

    setCoaches((prev) => {
      const updated = prev.map((c) => {
        if (c.id === coachId) {
          const currentReviews = c.reviews || [];
          const updatedReviews = [newReview, ...currentReviews];
          const newCount = updatedReviews.length;
          const totalRating = updatedReviews.reduce((sum, r) => sum + r.rating, 0);
          const newRating = Number((totalRating / newCount).toFixed(1));
          return {
            ...c,
            reviews: updatedReviews,
            reviewCount: newCount,
            rating: newRating
          };
        }
        return c;
      });

      try {
        localStorage.setItem('coachconnect_coaches', JSON.stringify(updated));
      } catch {}

      return updated;
    });

    // Also persist in dedicated reviews map
    try {
      const existingReviewsRaw = localStorage.getItem('coachconnect_reviews');
      const existingMap: Record<string, Review[]> = existingReviewsRaw ? JSON.parse(existingReviewsRaw) : {};
      const listForCoach = existingMap[coachId] || [];
      existingMap[coachId] = [newReview, ...listForCoach];
      localStorage.setItem('coachconnect_reviews', JSON.stringify(existingMap));
    } catch {}

    return newReview;
  };

