// lib/currency.ts
// Multi-currency conversion engine with support for INR, USD, GBP, EUR, AUD, AED, CAD, SGD

export interface CurrencyConfig {
  code: string;
  symbol: string;
  name: string;
  badge: string; // 2-letter uppercase country/region code e.g. "IN", "US"
  flag?: string;
  rateAgainstUSD: number; // 1 USD = X Currency
  decimals: number;
}

