export const DEFAULT_CURRENCY = 'INR';

/**
 * Normalizes symbol or code string into a standard currency code.
 */
export function normalizeCurrencyCode(cur?: string): string {
  if (!cur) return DEFAULT_CURRENCY;
  const upper = cur.trim().toUpperCase();
  if (upper === '₹' || upper === 'RS' || upper === 'INR') return 'INR';
  if (upper === '$' || upper === 'USD') return 'USD';
  if (upper === '€' || upper === 'EUR') return 'EUR';
  if (upper === '£' || upper === 'GBP') return 'GBP';
  if (upper.includes('AED') || upper.includes('DIRHAM')) return 'AED';
  if (upper.includes('AUD') || upper === 'A$') return 'AUD';
  if (upper.includes('CAD') || upper === 'C$') return 'CAD';
  if (upper.includes('SGD') || upper === 'S$') return 'SGD';

  if (SUPPORTED_CURRENCIES[upper]) return upper;
  return DEFAULT_CURRENCY;
}

/**
 * Converts an amount from one currency to another using exchange rates.
 */
export function convertCurrency(
  amount: number,
  fromCur: string = 'INR',
  toCur: string = 'INR'
): number {
  if (!amount || isNaN(amount)) return 0;
  const from = normalizeCurrencyCode(fromCur);
  const to = normalizeCurrencyCode(toCur);

  if (from === to) return amount;

  const fromRate = SUPPORTED_CURRENCIES[from]?.rateAgainstUSD || 1.0;
  const toRate = SUPPORTED_CURRENCIES[to]?.rateAgainstUSD || 1.0;

  // Amount in USD
  const amountInUSD = amount / fromRate;
  // Convert from USD to target currency
  const converted = amountInUSD * toRate;

  // Round intelligently based on currency scale
  if (to === 'INR' || to === 'AED') {
    return Math.round(converted);
  }
  return Math.round(converted * 10) / 10;
}

/**
 * Formats a currency amount with correct symbol and regional comma separators.
 */
export function formatCurrency(amount: number, currencyCode: string = 'INR'): string {
  const code = normalizeCurrencyCode(currencyCode);
  const conf = SUPPORTED_CURRENCIES[code] || SUPPORTED_CURRENCIES.INR;

  const rounded = Math.round(amount);
  const formattedNumber = rounded.toLocaleString('en-US');

  return `${conf.symbol}${formattedNumber}`;
}

/**
 * Convenience helper to convert and format a price in one call.
 */
export function convertAndFormatPrice(
  amount: number,
  fromCur: string = 'INR',
  targetCur: string = 'INR'
): string {
  if (amount === 0) return 'FREE';
  const converted = convertCurrency(amount, fromCur, targetCur);
  return formatCurrency(converted, targetCur);
}

