'use client';

import React from 'react';
import { Film, Play } from 'lucide-react';

interface CoachVideoEmbedProps {
  url: string;
  title?: string;
  className?: string;
}

export default function CoachVideoEmbed({ url, title = 'Coach Video Introduction', className = '' }: CoachVideoEmbedProps) {
  if (!url) return null;

  const trimmed = url.trim();

  // YouTube match
  const ytMatch = trimmed.match(/(?:youtu\.be\/|youtube\.com\/(?:embed\/|v\/|watch\?v=|watch\?.+&v=))([\w-]{11})/);
  if (ytMatch && ytMatch[1]) {
    return (
      <div className={`relative w-full aspect-video rounded-2xl overflow-hidden bg-slate-900 shadow-md ${className}`}>
        <iframe
          src={`https://www.youtube.com/embed/${ytMatch[1]}?rel=0&modestbranding=1`}
          title={title}
          allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
          allowFullScreen
          className="absolute inset-0 w-full h-full border-0"
        />
      </div>
    );
  }

  // Loom match
  if (trimmed.includes('loom.com')) {
    const loomMatch = trimmed.match(/loom\.com\/(?:share|embed)\/([a-zA-Z0-9]+)/);
    const loomId = loomMatch ? loomMatch[1] : trimmed.split('/').pop()?.split('?')[0];
    if (loomId) {
      return (
        <div className={`relative w-full aspect-video rounded-2xl overflow-hidden bg-slate-900 shadow-md ${className}`}>
          <iframe
            src={`https://www.loom.com/embed/${loomId}`}
            title={title}
            allowFullScreen
            className="absolute inset-0 w-full h-full border-0"
          />
        </div>
      );
    }
  }

  // Vimeo match
  const vimeoMatch = trimmed.match(/vimeo\.com\/(?:channels\/(?:\w+\/)?|groups\/(?:[^\/]*)\/videos\/|album\/(?:\d+)\/video\/|video\/|)(\d+)/);
  if (vimeoMatch && vimeoMatch[1]) {
    return (
      <div className={`relative w-full aspect-video rounded-2xl overflow-hidden bg-slate-900 shadow-md ${className}`}>
        <iframe
          src={`https://player.vimeo.com/video/${vimeoMatch[1]}?title=0&byline=0&portrait=0`}
          title={title}
          allow="autoplay; fullscreen; picture-in-picture"
          allowFullScreen
          className="absolute inset-0 w-full h-full border-0"
        />
      </div>
    );
  }

  // Direct video file (MP4, WebM, Supabase Storage, Cloudinary, etc.)
  return (
    <div className={`relative w-full aspect-video rounded-2xl overflow-hidden bg-black shadow-md ${className}`}>
      <video
        src={trimmed}
        controls
        playsInline
        preload="metadata"
        className="w-full h-full object-contain"
      >
        Your browser does not support the video tag.
      </video>
    </div>
  );
}

