const React = require('react');

function Image(props) {
  const { src, alt, width, height, fill, priority, quality, className, style, sizes, ...rest } = props;
  let imgStyle = Object.assign({}, style);
  if (fill) {
    imgStyle = Object.assign(
      {
        position: 'absolute',
        height: '100%',
        width: '100%',
        left: 0,
        top: 0,
        right: 0,
        bottom: 0,
        objectFit: 'cover',
      },
      imgStyle
    );
  }

  return React.createElement('img', {
    src: src,
    alt: alt || '',
    width: width,
    height: height,
    className: className,
    style: imgStyle,
    ...rest,
  });
}

module.exports = Image;
module.exports.default = Image;
