'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { useApp } from 'context/AppContext';
import { 
  Receipt, 
  ArrowLeft, 
  Printer, 
  Download, 
  CheckCircle2, 
  Calendar, 
  Globe, 
  ShieldCheck,
  CreditCard,
  Building
} from 'lucide-react';

export default function InvoicesPage() {
  const { bookings, currentUser } = useApp();
  const [selectedInvoiceId, setSelectedInvoiceId] = useState<string | null>(null);

  // Sample or real bookings mapped to invoices
  const invoices = (bookings.length > 0 ? bookings : [
    {
      id: 'inv-sample-1',
      coachName: 'Dr. Neha Sharma',
      serviceTitle: '1:1 Discovery & Metabolic Strategy Session',
      servicePrice: 1500,
      currency: '₹',
      currencyCode: 'INR',
      country: 'India',
      taxRate: 0.18, // 18% GST
      date: '2026-10-28',
      timeSlot: '03:00 PM - 04:00 PM IST',
      clientName: currentUser?.fullName || 'Valued Client',
      clientEmail: currentUser?.email || 'client@example.com',
      invoiceNumber: 'CC-INV-2026-1082'
    },
    {
      id: 'inv-sample-2',
      coachName: 'Marcus Vance',
      serviceTitle: 'Executive Leadership Strategy Call',
      servicePrice: 85,
      currency: '$',
      currencyCode: 'USD',
      country: 'United States',
      taxRate: 0.08, // 8% Sales Tax
      date: '2026-10-15',
      timeSlot: '11:00 AM - 12:00 PM EST',
      clientName: currentUser?.fullName || 'Valued Client',
      clientEmail: currentUser?.email || 'client@example.com',
      invoiceNumber: 'CC-INV-2026-0974'
    }
  ]).map((b: any, index: number) => {
    const price = b.servicePrice || 1500;
    const cur = b.currency || '₹';
    const taxRate = b.taxRate ?? (cur === '₹' ? 0.18 : 0.08);
    const taxAmount = Math.round(price * taxRate);
    const totalAmount = price + taxAmount;
    const invNo = b.invoiceNumber || `CC-INV-2026-${String(index + 1040).padStart(4, '0')}`;

    return {
      id: b.id,
      invoiceNumber: invNo,
      coachName: b.coachName,
      serviceTitle: b.serviceTitle,
      date: b.date || '2026-10-29',
      timeSlot: b.timeSlot || '02:00 PM',
      currency: cur,
      currencyCode: cur === '₹' ? 'INR' : cur === '$' ? 'USD' : cur === '€' ? 'EUR' : cur === '£' ? 'GBP' : 'AED',
      basePrice: price,
      taxAmount,
      taxLabel: cur === '₹' ? 'CGST + SGST (18%)' : 'Applicable Tax/VAT',
      totalAmount,
      clientName: b.clientName || currentUser?.fullName || 'Client',
      clientEmail: b.clientEmail || currentUser?.email || 'client@example.com',
      status: 'Paid'
    };
  });

  const activeInvoice = invoices.find(inv => inv.id === selectedInvoiceId) || invoices[0];

  const handlePrint = () => {
    if (typeof window !== 'undefined') {
      window.print();
    }
  };

  return (
    <div className="bg-[#FAF8F6] min-h-screen py-10 print:bg-white print:py-0">
      <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8">
        
        {/* Navigation & Header (Hidden on print) */}
        <div className="print:hidden mb-6 flex items-center justify-between">
          <Link 
            href="/dashboard/client" 
            className="inline-flex items-center gap-1.5 text-xs font-semibold text-slate-500 hover:text-red-600 transition-colors"
          >
            <ArrowLeft className="w-4 h-4" />
            <span>Back to Dashboard</span>
          </Link>

          <button
            onClick={handlePrint}
            className="btn-glossy-pill px-5 py-2 text-xs font-bold flex items-center gap-2 cursor-pointer shadow-xs"
          >
            <Printer className="w-4 h-4" />
            <span>Print / Save as PDF</span>
          </button>
        </div>

        {/* Invoice Selector Tabs (Hidden on print) */}
        {invoices.length > 1 && (
          <div className="print:hidden mb-6 flex gap-2 overflow-x-auto pb-2">
            {invoices.map((inv) => (
              <button
                key={inv.id}
                onClick={() => setSelectedInvoiceId(inv.id)}
                className={`px-4 py-2 rounded-xl text-xs font-bold transition-all border cursor-pointer whitespace-nowrap ${
                  activeInvoice.id === inv.id
                    ? 'bg-red-600 text-white border-red-600 shadow-sm'
                    : 'bg-white text-slate-700 border-slate-200 hover:bg-slate-50'
                }`}
              >
                {inv.invoiceNumber} • {inv.currency}{inv.totalAmount}
              </button>
            ))}
          </div>
        )}

        {/* Printable Invoice Card */}
        <div className="bg-white rounded-3xl p-8 sm:p-12 border border-slate-200/80 shadow-md print:border-none print:shadow-none print:p-0">
          
          {/* Invoice Header */}
          <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between pb-8 border-b border-slate-100 gap-4">
            <div>
              <div className="flex items-center gap-2">
                <span className="text-2xl font-black text-slate-900 tracking-tight">
                  Coach<span className="text-red-600">Connect</span>
                </span>
                <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-emerald-50 text-emerald-700 border border-emerald-200">
                  OFFICIAL TAX INVOICE
                </span>
              </div>
              <p className="text-xs text-slate-500 mt-1">Verified Coaching Platform Ltd.</p>
              <p className="text-[11px] text-slate-400">GSTIN / Tax ID: 27AABCC1234F1Z5 • Support: techshad04@gmail.com</p>
            </div>

            <div className="sm:text-right">
              <div className="text-sm font-black text-slate-900">{activeInvoice.invoiceNumber}</div>
              <div className="text-xs text-slate-500">Date: {activeInvoice.date}</div>
              <div className="mt-1 inline-flex items-center gap-1 text-xs font-bold text-emerald-700 bg-emerald-50 px-2.5 py-0.5 rounded-full border border-emerald-200">
                <CheckCircle2 className="w-3.5 h-3.5" /> Paid in Full
              </div>
            </div>
          </div>

          {/* Billed To & Service Details */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-8 py-8 border-b border-slate-100 text-xs">
            <div>
              <span className="font-bold text-slate-400 uppercase tracking-wider block mb-2">Billed To (Client):</span>
              <div className="font-bold text-sm text-slate-900">{activeInvoice.clientName}</div>
              <div className="text-slate-600 mt-0.5">{activeInvoice.clientEmail}</div>
              <div className="text-slate-400 mt-1">Place of Supply: International Consumer Services</div>
            </div>

            <div className="sm:text-right">
              <span className="font-bold text-slate-400 uppercase tracking-wider block mb-2">Service Provider (Coach):</span>
              <div className="font-bold text-sm text-slate-900">{activeInvoice.coachName}</div>
              <div className="text-slate-600 mt-0.5">Verified Professional Coach</div>
              <div className="text-slate-400 mt-1">Session Slot: {activeInvoice.timeSlot}</div>
            </div>
          </div>

          {/* Line Items Table */}
          <div className="py-6">
            <table className="w-full text-left text-xs">
              <thead>
                <tr className="border-b border-slate-200 text-slate-400 font-bold uppercase tracking-wider">
                  <th className="pb-3">Description</th>
                  <th className="pb-3 text-center">Qty</th>
                  <th className="pb-3 text-right">Unit Price</th>
                  <th className="pb-3 text-right">Amount</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                <tr>
                  <td className="py-4">
                    <div className="font-bold text-slate-900 text-sm">{activeInvoice.serviceTitle}</div>
                    <div className="text-slate-500 text-[11px] mt-0.5">1:1 High-Definition Zoom Mentorship Session</div>
                  </td>
                  <td className="py-4 text-center font-bold text-slate-700">1</td>
                  <td className="py-4 text-right font-medium text-slate-700">
                    {activeInvoice.currency}{activeInvoice.basePrice.toLocaleString()}
                  </td>
                  <td className="py-4 text-right font-bold text-slate-900">
                    {activeInvoice.currency}{activeInvoice.basePrice.toLocaleString()}
                  </td>
                </tr>
              </tbody>
            </table>
          </div>

          {/* Totals Breakdown */}
          <div className="pt-4 border-t border-slate-200 flex flex-col sm:flex-row justify-between gap-6 text-xs">
            <div className="space-y-1 text-slate-500 max-w-sm">
              <p><strong>Payment Method:</strong> Secure International Gateway / Card</p>
              <p><strong>Currency:</strong> {activeInvoice.currencyCode} ({activeInvoice.currency})</p>
              <p className="text-[11px] text-slate-400">This is a computer-generated invoice and requires no physical signature.</p>
            </div>

            <div className="w-full sm:w-64 space-y-2 text-right">
              <div className="flex justify-between text-slate-600">
                <span>Subtotal:</span>
                <span className="font-semibold text-slate-900">{activeInvoice.currency}{activeInvoice.basePrice.toLocaleString()}</span>
              </div>
              <div className="flex justify-between text-slate-600">
                <span>{activeInvoice.taxLabel}:</span>
                <span className="font-semibold text-slate-900">{activeInvoice.currency}{activeInvoice.taxAmount.toLocaleString()}</span>
              </div>
              <div className="flex justify-between text-base font-black text-slate-900 pt-2 border-t border-slate-200">
                <span>Total Paid:</span>
                <span className="text-red-600">{activeInvoice.currency}{activeInvoice.totalAmount.toLocaleString()}</span>
              </div>
            </div>
          </div>

        </div>

      </div>
    </div>
  );
}

