  const handleDashboardPhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsUploadingPhoto(true);
    setPhotoUploadStatus(null);
    try {
      const res = await uploadToSupabaseStorage(file, 'avatars');
      setProfileForm(prev => ({ ...prev, photoUrl: res.url }));
      const sizeKb = Math.round((res.sizeBytes || file.size) / 1024);
      setPhotoUploadStatus(res.isFallback ? `✓ Photo attached (${sizeKb} KB optimized)` : `✓ Uploaded to Supabase 'coach-assets' (${sizeKb} KB)`);
    } catch {
      setPhotoUploadStatus('Photo attached.');
    } finally {
      setIsUploadingPhoto(false);
    }
  };

