    setIsUploadingVideo(true);
    setVideoUploadStatus(null);
    try {
      const res = await uploadToSupabaseStorage(file, 'videos');
      setProfileForm(prev => ({ ...prev, videoIntroUrl: res.url }));
      const sizeMb = (file.size / (1024 * 1024)).toFixed(1);
      setVideoUploadStatus(res.isFallback ? `✓ Video attached (${sizeMb} MB)` : `✓ Video uploaded to Supabase (${sizeMb} MB)`);
    } catch {
      setVideoUploadStatus('Video attached.');
    } finally {
      setIsUploadingVideo(false);
    }
