'use client';

import React, { useState } from 'react';
import { FAQ_ITEMS } from 'data/coachesData';
import { ChevronDown, HelpCircle, ShieldAlert, MessageSquare } from 'lucide-react';
import { HandDrawnArrow } from 'components/ui/HandDrawnArrow';

export default function FAQSection() {
  const [openIndex, setOpenIndex] = useState<number | null>(0);

  const toggleItem = (idx: number) => {
    setOpenIndex(openIndex === idx ? null : idx);
  };

  return (
    <section id="faq" className="py-16 bg-white border-t border-slate-100">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8">
        
        {/* Section Header */}
        <div className="text-center mb-12">
          <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-slate-100 text-slate-700 text-xs font-bold uppercase tracking-wider mb-2">
            <HelpCircle className="w-3.5 h-3.5 text-red-500" />
            <span>Got Questions? We Have Answers</span>
          </div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">
            Frequently Asked <span className="text-red-600">Questions</span>
          </h2>
          <p className="text-slate-500 text-sm mt-1">
            Everything you need to know about coach credentialing, booking sessions, and policies.
          </p>
        </div>

        {/* Accordion list */}
        <div className="space-y-3">
          {FAQ_ITEMS.map((item, idx) => {
            const isOpen = openIndex === idx;
            const isAlert = item.question.includes('Notice');

            return (
              <div
                key={idx}
                className={`rounded-2xl border transition-all duration-200 overflow-hidden ${
                  isOpen 
                    ? isAlert ? 'border-amber-300 bg-amber-50/40' : 'border-red-200 bg-red-50/20 shadow-xs' 
                    : 'border-slate-200/80 bg-white hover:border-slate-300'
                }`}
              >
                <button
                  type="button"
                  onClick={() => toggleItem(idx)}
                  className="w-full py-4 px-6 text-left flex items-center justify-between gap-4 font-bold text-slate-900 text-sm sm:text-base focus:outline-hidden"
                >
                  <span className={`flex items-center gap-2 ${isAlert ? 'text-amber-900 font-black' : ''}`}>
                    {isAlert && <ShieldAlert className="w-4 h-4 text-amber-600 shrink-0" />}
                    {item.question}
                  </span>
                  <ChevronDown
                    className={`w-5 h-5 text-slate-400 shrink-0 transition-transform duration-200 ${
                      isOpen ? 'rotate-180 text-red-600' : ''
                    }`}
                  />
                </button>

                {isOpen && (
                  <div className="px-6 pb-5 pt-1 text-slate-600 text-xs sm:text-sm leading-relaxed border-t border-slate-100/60">
                    {item.answer}
                  </div>
                )}
              </div>
            );
          })}
        </div>

        {/* Help Banner with Hand-Drawn Arrow */}
        <div className="mt-10 p-6 rounded-3xl bg-slate-50 border border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-4">
          <div className="flex items-center gap-3 text-center sm:text-left">
            <div className="w-10 h-10 rounded-2xl bg-red-100 text-red-600 flex items-center justify-center shrink-0">
              <MessageSquare className="w-5 h-5" />
            </div>
            <div>
              <h4 className="font-bold text-slate-900 text-sm">Still have questions?</h4>
              <p className="text-xs text-slate-500">Our coach matching team is ready to help you find the right fit.</p>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <div className="hidden sm:inline-flex">
              <HandDrawnArrow 
                direction="up-right" 
                label="Free 1:1 Matching Call" 
                className="w-10 h-6" 
                color="#E02B20" 
              />
            </div>
            <a
              href="mailto:support@coachconnect.org"
              className="px-5 py-2.5 rounded-full text-xs font-bold text-white bg-red-600 hover:bg-red-700 transition-colors shadow-xs"
            >
              Contact Support
            </a>
          </div>
        </div>

      </div>
    </section>
  );
}
