'use client';

import React, { useState, useEffect, useMemo } from 'react';
import { getAllCountries, LocationCountry } from 'lib/locationService';
import { Phone, ChevronDown } from 'lucide-react';

interface PhoneInputWithCountryCodeProps {
  value: string;
  onChange: (fullPhone: string) => void;
  required?: boolean;
  label?: string;
  id?: string;
  placeholder?: string;
  disabled?: boolean;
  className?: string;
  error?: string;
}

// Top priority country ISO codes for fast selection
const PRIORITY_ISO_CODES = ['IN', 'US', 'GB', 'AE', 'CA', 'AU', 'SG', 'DE', 'FR'];

export default function PhoneInputWithCountryCode({
  value,
  onChange,
  required = true,
  label = 'Phone Number',
  id,
  placeholder = '98765 43210',
  disabled = false,
  className = '',
  error
}: PhoneInputWithCountryCodeProps) {
  const allCountries = useMemo(() => {
    try {
      const list = getAllCountries();
      // Put priority countries at the top
      const priority = list.filter((c) => PRIORITY_ISO_CODES.includes(c.isoCode));
      const others = list.filter((c) => !PRIORITY_ISO_CODES.includes(c.isoCode));
      return [...priority, ...others];
    } catch {
      return [
        { name: 'India', isoCode: 'IN', phonecode: '+91', currency: 'INR', currencySymbol: '₹' },
        { name: 'United States', isoCode: 'US', phonecode: '+1', currency: 'USD', currencySymbol: '$' },
        { name: 'United Kingdom', isoCode: 'GB', phonecode: '+44', currency: 'GBP', currencySymbol: '£' },
        { name: 'United Arab Emirates', isoCode: 'AE', phonecode: '+971', currency: 'AED', currencySymbol: 'AED' },
        { name: 'Canada', isoCode: 'CA', phonecode: '+1', currency: 'CAD', currencySymbol: 'C$' },
        { name: 'Australia', isoCode: 'AU', phonecode: '+61', currency: 'AUD', currencySymbol: 'A$' },
        { name: 'Singapore', isoCode: 'SG', phonecode: '+65', currency: 'SGD', currencySymbol: 'S$' },
      ];
    }
  }, []);

  // Parse initial value if it starts with a country dial code
  const initialParse = useMemo(() => {
    const trimmed = (value || '').trim();
    if (trimmed.startsWith('+')) {
      // Find matching country code (longest match first)
      const sortedCodes = [...allCountries].sort((a, b) => b.phonecode.length - a.phonecode.length);
      const match = sortedCodes.find((c) => trimmed.startsWith(c.phonecode));
      if (match) {
        const raw = trimmed.slice(match.phonecode.length).trim();
        return { dialCode: match.phonecode, raw };
      }
    }
    return { dialCode: '+91', raw: trimmed };
  }, [value, allCountries]);

  const [selectedDialCode, setSelectedDialCode] = useState<string>(initialParse.dialCode);
  const [rawNumber, setRawNumber] = useState<string>(initialParse.raw);

  // Sync when prop value changes from outside
  useEffect(() => {
    const trimmed = (value || '').trim();
    if (trimmed.startsWith('+')) {
      const sortedCodes = [...allCountries].sort((a, b) => b.phonecode.length - a.phonecode.length);
      const match = sortedCodes.find((c) => trimmed.startsWith(c.phonecode));
      if (match) {
        setSelectedDialCode(match.phonecode);
        setRawNumber(trimmed.slice(match.phonecode.length).trim());
        return;
      }
    }
    setRawNumber(trimmed);
  }, [value, allCountries]);

  const handleDialCodeChange = (newDialCode: string) => {
    setSelectedDialCode(newDialCode);
    const formatted = rawNumber ? `${newDialCode} ${rawNumber}`.trim() : '';
    onChange(formatted);
  };

  const handleNumberChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    // Keep numbers, spaces, and hyphens only
    const clean = e.target.value.replace(/[^\d\s-]/g, '');
    setRawNumber(clean);
    const formatted = clean ? `${selectedDialCode} ${clean}`.trim() : '';
    onChange(formatted);
  };

  // Find currently selected country metadata
  const currentCountry = allCountries.find((c) => c.phonecode === selectedDialCode) || allCountries[0];

  return (
    <div className={`space-y-1.5 ${className}`}>
      {label && (
        <label htmlFor={id} className="block text-xs font-bold text-slate-700">
          {label} {required && <span className="text-red-500 font-black">*</span>}
        </label>
      )}

      <div className="flex items-center rounded-xl border border-slate-200 bg-white shadow-2xs focus-within:border-red-500 focus-within:ring-2 focus-within:ring-red-500/10 transition-all overflow-hidden">
        
        {/* Country Code Prefix Selector */}
        <div className="relative shrink-0 flex items-center bg-slate-50 border-r border-slate-200 px-2.5 py-2 hover:bg-slate-100 transition-colors cursor-pointer group">
          <span className="px-1.5 py-0.5 rounded-md bg-slate-200/80 text-slate-800 text-[10px] font-bold tracking-wider mr-1.5 select-none" aria-hidden="true">
            {currentCountry?.isoCode || 'IN'}
          </span>
          <span className="text-xs font-bold text-slate-800">
            {selectedDialCode}
          </span>
          <ChevronDown className="w-3 h-3 text-slate-400 ml-1 group-hover:text-slate-700 transition-colors" />

          {/* Native Select overlaid for reliable cross-browser accessibility */}
          <select
            value={selectedDialCode}
            disabled={disabled}
            onChange={(e) => handleDialCodeChange(e.target.value)}
            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer text-xs"
            aria-label="Select Country Dial Code"
          >
            {allCountries.map((c, idx) => (
              <option key={`${c.isoCode}-${c.phonecode}-${idx}`} value={c.phonecode}>
                [{c.isoCode}] {c.name} ({c.phonecode})
              </option>
            ))}
          </select>
        </div>

        {/* Raw Phone Number Input */}
        <div className="relative flex-1 flex items-center">
          <Phone className="w-3.5 h-3.5 text-slate-400 absolute left-3 pointer-events-none" />
          <input
            id={id}
            type="tel"
            required={required}
            disabled={disabled}
            value={rawNumber}
            onChange={handleNumberChange}
            placeholder={placeholder}
            className="w-full pl-8 pr-3.5 py-2.5 text-xs sm:text-sm font-semibold text-slate-900 placeholder:text-slate-400 focus:outline-hidden bg-transparent"
          />
        </div>

      </div>

      {error && (
        <p className="text-[11px] text-red-500 font-medium">{error}</p>
      )}
    </div>
  );
}

