'use client';

import React, { useRef } from 'react';
import { motion, useInView, Variants } from 'motion/react';
import { cn } from 'lib/utils';

interface RevealProps {
  children: React.ReactNode;
  width?: 'fit-content' | '100%';
  delay?: number;
  duration?: number;
  direction?: 'up' | 'down' | 'left' | 'right' | 'none';
  distance?: number;
  className?: string;
  once?: boolean;
  blur?: string;
}

/**
 * Pure Blur Reveal Animation (Magic UI BlurFade Principle)
 * Crisp 4px optical focus, zero layout jump, butter smooth 120fps
 */
export function Reveal({
  children,
  width = '100%',
  delay = 0,
  duration = 0.28,
  className,
  once = true,
  blur = '4px',
}: RevealProps) {
  const ref = useRef(null);
  const isInView = useInView(ref, { once, margin: '0px 0px 120px 0px' });

  return (
    <div ref={ref} style={{ width }} className={cn("relative", className)}>
      <motion.div
        initial={{ opacity: 0, filter: `blur(${blur})` }}
        animate={isInView ? { opacity: 1, filter: 'blur(0px)' } : { opacity: 0, filter: `blur(${blur})` }}
        transition={{
          duration,
          delay,
          ease: [0.16, 1, 0.3, 1],
        }}
        className="will-change-[filter,opacity]"
      >
        {children}
      </motion.div>
    </div>
  );
}

export function StaggerContainer({
  children,
  className,
  staggerDelay = 0.04,
  once = true,
}: {
  children: React.ReactNode;
  className?: string;
  staggerDelay?: number;
  once?: boolean;
}) {
  const ref = useRef(null);
  const isInView = useInView(ref, { once, margin: '0px 0px 120px 0px' });

  const containerVariants: Variants = {
    hidden: { opacity: 0 },
    show: {
      opacity: 1,
      transition: {
        staggerChildren: staggerDelay,
      },
    },
  };

  return (
    <motion.div
      ref={ref}
      variants={containerVariants}
      initial="hidden"
      animate={isInView ? "show" : "hidden"}
      className={className}
    >
      {children}
    </motion.div>
  );
}

export function StaggerItem({
  children,
  className,
  blur = '4px',
}: {
  children: React.ReactNode;
  className?: string;
  blur?: string;
}) {
  const itemVariants: Variants = {
    hidden: { opacity: 0, filter: `blur(${blur})` },
    show: {
      opacity: 1,
      filter: 'blur(0px)',
      transition: {
        duration: 0.28,
        ease: [0.16, 1, 0.3, 1],
      },
    },
  };

  return (
    <motion.div variants={itemVariants} className={cn("will-change-[filter,opacity]", className)}>
      {children}
    </motion.div>
  );
}

export function WordReveal({
  text,
  className,
  delay = 0,
}: {
  text: string;
  className?: string;
  delay?: number;
}) {
  const words = text.split(" ");
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: '0px 0px 120px 0px' });

  return (
    <span ref={ref} className={cn("inline-block", className)}>
      {words.map((word, i) => (
        <motion.span
          key={i}
          initial={{ opacity: 0, filter: 'blur(4px)' }}
          animate={isInView ? { opacity: 1, filter: 'blur(0px)' } : { opacity: 0, filter: 'blur(4px)' }}
          transition={{
            duration: 0.25,
            delay: delay + i * 0.03,
            ease: [0.16, 1, 0.3, 1],
          }}
          className="inline-block mr-[0.25em] will-change-[filter,opacity]"
        >
          {word}
        </motion.span>
      ))}
    </span>
  );
}

export default Reveal;
