const React = require('react');
const { Link: RouterLink } = require('react-router-dom');

const Link = React.forwardRef(function Link(props, ref) {
  const { href, to, children, prefetch, scroll, ...rest } = props;
  const dest = to || href || '/';
  const destination = typeof dest === 'object' && dest.pathname
    ? dest.pathname + (dest.query ? '?' + new URLSearchParams(dest.query).toString() : '')
    : String(dest);

  if (destination.startsWith('http://') || destination.startsWith('https://') || destination.startsWith('mailto:') || destination.startsWith('tel:')) {
    return React.createElement('a', { ref, href: destination, ...rest }, children);
  }

  return React.createElement(RouterLink, { ref, to: destination, ...rest }, children);
});

Link.displayName = 'Link';
module.exports = Link;
module.exports.default = Link;
