'use client';

import React from 'react';
import Link from 'next/link';
import { useApp } from 'context/AppContext';
import { convertAndFormatPrice } from 'lib/currency';
import { motion } from 'motion/react';
import { 
  Star, 
  Video, 
  ArrowRight, 
  Heart, 
  ShieldCheck, 
  Sparkles,
  Clock
} from 'lucide-react';

export default function FeaturedCoaches() {
  const { coaches, isCoachSaved, toggleSaveCoach, selectedCurrency, apiError, isLoadingData } = useApp();

  // Top 4 featured coaches
  const featured = coaches.slice(0, 4);

  return (
    <section className="py-16 sm:py-20 lg:py-24 bg-white border-b border-slate-100">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        
        {/* Section Header */}
        <div className="flex flex-col sm:flex-row sm:items-end justify-between mb-12 gap-4">
          <div>
            <div className="inline-flex items-center gap-2 text-xs font-bold tracking-widest text-[#E02B20] uppercase mb-2">
              <Sparkles className="w-3.5 h-3.5" />
              <span>HANDPICKED TOP 1% MENTORS</span>
            </div>
            <h2 className="text-3xl sm:text-4xl font-black text-slate-950 tracking-tight leading-tight">
              Featured <span className="text-[#E02B20]">Certified Coaches</span>
            </h2>
            <p className="text-slate-500 text-sm sm:text-base mt-1.5 max-w-xl">
              Strictly vetted credentials, verified client outcomes, and proven track records.
            </p>
          </div>
          
          <Link
            href="/coaches"
            className="btn-glossy-pill px-5 py-2.5 text-xs font-bold flex items-center gap-2"
          >
            <span>Browse All Coaches</span>
            <ArrowRight className="w-3.5 h-3.5" />
          </Link>
        </div>

        {/* API Error Warning */}
        {apiError && (
          <div className="mb-6 bg-red-50 border border-red-200 text-red-800 px-4 py-3 rounded-2xl text-xs sm:text-sm font-semibold flex items-center justify-between">
            <span>⚠️ Unable to load live coaches: {apiError}</span>
            <button onClick={() => window.location.reload()} className="px-3 py-1 bg-red-600 text-white rounded-full text-xs font-bold">Retry</button>
          </div>
        )}

        {/* Coaches Grid */}
        {isLoadingData && featured.length === 0 ? (
          <div className="bg-slate-50 rounded-3xl p-12 text-center border border-slate-200 text-sm font-semibold text-slate-500">
            Loading live certified coaches from server...
          </div>
        ) : featured.length === 0 ? (
          <div className="bg-slate-50 rounded-3xl p-12 text-center border border-slate-200 space-y-3">
            <Sparkles className="w-10 h-10 text-red-500 mx-auto" />
            <h3 className="text-base font-bold text-slate-800">Directory Ready for New Mentors</h3>
            <p className="text-xs text-slate-500 max-w-md mx-auto">
              No featured coaches are currently listed. Apply now to become a founding verified mentor on the platform.
            </p>
            <Link
              href="/join-coach"
              className="btn-glossy-pill inline-block px-5 py-2.5 text-xs font-bold text-white shadow-md mt-2"
            >
              Apply as a Coach →
            </Link>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            {featured.map((coach, idx) => {
            const isSaved = isCoachSaved(coach.id);
            return (
              <motion.div
                key={coach.id}
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ duration: 0.45, delay: idx * 0.08 }}
                whileHover={{ y: -5 }}
                className="bg-white rounded-3xl border border-slate-200/80 hover:border-red-200 overflow-hidden shadow-xs hover:shadow-xl hover:shadow-red-500/8 transition-all flex flex-col justify-between group"
              >
                <div>
                  {/* Image & Badges */}
                  <div className="relative h-56 w-full overflow-hidden bg-slate-100">
                    <img
                      src={coach.photoUrl}
                      alt={coach.name}
                      className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                    />
                    
                    {/* Gradient Overlay */}
                    <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent pointer-events-none" />

                    {/* Category pill */}
                    <span className="absolute top-3 left-3 px-3 py-1 rounded-full bg-white/90 backdrop-blur-md text-[11px] font-bold text-slate-800 shadow-xs">
                      {coach.primaryCategory}
                    </span>

                    {/* Save / Favorite Button */}
                    <button
                      onClick={(e) => {
                        e.preventDefault();
                        toggleSaveCoach(coach.id);
                      }}
                      className="absolute top-3 right-3 w-8 h-8 rounded-full bg-white/90 backdrop-blur-md flex items-center justify-center text-slate-700 hover:text-red-600 transition-colors shadow-xs cursor-pointer"
                      title={isSaved ? 'Remove from saved' : 'Save coach'}
                    >
                      <Heart className={`w-4 h-4 ${isSaved ? 'fill-red-600 text-red-600' : ''}`} />
                    </button>

                    {/* Bottom overlay: Rating & Experience */}
                    <div className="absolute bottom-3 left-3 right-3 flex items-center justify-between text-white text-xs">
                      {coach.reviewCount > 0 ? (
                        <div className="flex items-center gap-1 font-bold">
                          <Star className="w-3.5 h-3.5 fill-amber-400 text-amber-400" />
                          <span>{coach.rating}</span>
                          <span className="text-slate-300 font-normal">({coach.reviewCount})</span>
                        </div>
                      ) : (
                        <div className="inline-flex items-center gap-1 font-semibold text-emerald-300 text-xs">
                          <Sparkles className="w-3.5 h-3.5 text-emerald-300" />
                          <span>New Coach</span>
                        </div>
                      )}
                      <span className="flex items-center gap-1 text-[11px] font-medium text-slate-200">
                        <Clock className="w-3 h-3" /> {coach.experienceYears}+ yrs exp
                      </span>
                    </div>
                  </div>

                  {/* Card Body */}
                  <div className="p-5">
                    {/* Coach Name with Verified Icon */}
                    <div className="flex items-center gap-1.5">
                      <h3 className="text-base font-bold text-slate-900 group-hover:text-[#E02B20] transition-colors">
                        {coach.name}
                      </h3>
                      {coach.verified && (
                        <span title="Verified Credentials" className="inline-flex items-center">
                          <ShieldCheck className="w-4 h-4 text-emerald-600 shrink-0" />
                        </span>
                      )}
                    </div>

                    {/* Headline */}
                    <p className="text-xs text-slate-500 mt-1 line-clamp-2 leading-relaxed">
                      {coach.headline}
                    </p>

                    {/* Specialties Pills */}
                    <div className="mt-3 flex flex-wrap gap-1">
                      {coach.specialties.slice(0, 2).map((s) => (
                        <span
                          key={s}
                          className="px-2 py-0.5 rounded-md bg-slate-50 text-[10px] font-medium text-slate-600 border border-slate-100"
                        >
                          {s}
                        </span>
                      ))}
                    </div>
                  </div>
                </div>

                {/* Card Footer: Price & CTA */}
                <div className="px-5 pb-5 pt-3 border-t border-slate-100 flex items-center justify-between">
                  <div>
                    <span className="block text-[10px] font-medium text-slate-400 uppercase tracking-wider">
                      Starting at
                    </span>
                    <div className="text-base font-black text-slate-900">
                      {convertAndFormatPrice(coach.startingPrice, coach.currency || 'INR', selectedCurrency)}
                      <span className="text-xs font-normal text-slate-500">/session</span>
                    </div>
                  </div>

                  <Link
                    href={`/coaches/${coach.id}`}
                    className="btn-glossy-pill px-4 py-2 text-xs font-bold flex items-center gap-1.5"
                  >
                    <span>View Profile</span>
                    <ArrowRight className="w-3 h-3 stroke-[2.5]" />
                  </Link>
                </div>

              </motion.div>
            );
          })}
        </div>
        )}

      </div>
    </section>
  );
}
