'use client';

import React from 'react';

interface HandDrawnArrowProps {
  direction?: 'up-right' | 'down-right' | 'curved-down' | 'curved-up' | 'loop';
  className?: string;
  color?: string;
  label?: string;
  labelPosition?: 'top' | 'bottom' | 'left' | 'right';
  labelClassName?: string;
}

export function HandDrawnArrow({
  direction = 'up-right',
  className = 'w-16 h-12',
  color = '#7A354E',
  label,
  labelPosition = 'right',
  labelClassName = ''
}: HandDrawnArrowProps) {
  return (
    <div className="inline-flex items-center gap-2 select-none pointer-events-none group">
      {label && (labelPosition === 'left' || labelPosition === 'top') && (
        <span 
          className={`font-handwriting text-xs italic tracking-wide font-bold shrink-0 transition-transform group-hover:scale-105 ${labelClassName}`}
          style={{ color, fontFamily: 'Comic Sans MS, cursive, sans-serif' }}
        >
          {label}
        </span>
      )}

      <div className={`relative ${className}`}>
        {direction === 'up-right' && (
          <svg 
            viewBox="0 0 100 80" 
            className="w-full h-full overflow-visible transition-transform hover:scale-105"
            style={{ color, filter: `drop-shadow(0 2px 4px ${color}33)` }}
          >
            {/* Curved Tail */}
            <path
              d="M 10 65 Q 45 60 82 22"
              fill="none"
              stroke="currentColor"
              strokeWidth="4"
              strokeLinecap="round"
              className="animate-arrow-draw"
              strokeDasharray="95"
              strokeDashoffset="95"
            />
            {/* Arrowhead */}
            <path
              d="M 62 25 L 83 20 L 85 42"
              fill="none"
              stroke="currentColor"
              strokeWidth="4"
              strokeLinecap="round"
              strokeLinejoin="round"
              className="animate-arrow-head"
              strokeDasharray="50"
              strokeDashoffset="50"
            />
          </svg>
        )}

        {direction === 'down-right' && (
          <svg 
            viewBox="0 0 90 80" 
            className="w-full h-full overflow-visible transition-transform hover:scale-105"
            style={{ color, filter: `drop-shadow(0 2px 4px ${color}33)` }}
          >
            <path
              d="M 12 18 Q 20 62 68 65"
              fill="none"
              stroke="currentColor"
              strokeWidth="4"
              strokeLinecap="round"
              className="animate-arrow-draw"
              strokeDasharray="95"
              strokeDashoffset="95"
            />
            <path
              d="M 48 55 L 70 66 L 58 45"
              fill="none"
              stroke="currentColor"
              strokeWidth="4"
              strokeLinecap="round"
              strokeLinejoin="round"
              className="animate-arrow-head"
              strokeDasharray="50"
              strokeDashoffset="50"
            />
          </svg>
        )}

        {direction === 'curved-down' && (
          <svg 
            viewBox="0 0 80 80" 
            className="w-full h-full overflow-visible"
            style={{ color, filter: `drop-shadow(0 2px 4px ${color}33)` }}
          >
            <path
              d="M 15 20 Q 55 10 60 55"
              fill="none"
              stroke="currentColor"
              strokeWidth="4"
              strokeLinecap="round"
              className="animate-arrow-draw"
              strokeDasharray="90"
              strokeDashoffset="90"
            />
            <path
              d="M 48 42 L 60 58 L 72 44"
              fill="none"
              stroke="currentColor"
              strokeWidth="4"
              strokeLinecap="round"
              strokeLinejoin="round"
              className="animate-arrow-head"
              strokeDasharray="45"
              strokeDashoffset="45"
            />
          </svg>
        )}

        {direction === 'curved-up' && (
          <svg 
            viewBox="0 0 80 80" 
            className="w-full h-full overflow-visible"
            style={{ color, filter: `drop-shadow(0 2px 4px ${color}33)` }}
          >
            <path
              d="M 15 65 Q 35 15 65 20"
              fill="none"
              stroke="currentColor"
              strokeWidth="4"
              strokeLinecap="round"
              className="animate-arrow-draw"
              strokeDasharray="90"
              strokeDashoffset="90"
            />
            <path
              d="M 50 12 L 67 20 L 58 35"
              fill="none"
              stroke="currentColor"
              strokeWidth="4"
              strokeLinecap="round"
              strokeLinejoin="round"
              className="animate-arrow-head"
              strokeDasharray="45"
              strokeDashoffset="45"
            />
          </svg>
        )}
      </div>

      {label && (labelPosition === 'right' || labelPosition === 'bottom') && (
        <span 
          className={`font-handwriting text-xs italic tracking-wide font-bold shrink-0 transition-transform group-hover:scale-105 ${labelClassName}`}
          style={{ color, fontFamily: 'Comic Sans MS, cursive, sans-serif' }}
        >
          {label}
        </span>
      )}
    </div>
  );
}
