// lib/timezones.ts
// International Time Zone utility: Normalizes time zones, converts slot timings, and formats real-time clocks.

export interface TimeZoneOption {
  code: string;       // IANA identifier, e.g. "Asia/Kolkata"
  name: string;
  utcOffset: string;
  city: string;
  badge: string;      // 2-letter uppercase badge e.g. "IN", "US"
  flag?: string;
  shortCode: string;  // e.g. "IST"
}

export const POPULAR_TIMEZONES: TimeZoneOption[] = [
  { code: 'Asia/Kolkata', name: 'India Standard Time (IST)', utcOffset: '+05:30', city: 'Mumbai / Delhi', badge: 'IN', flag: 'IN', shortCode: 'IST' },
  { code: 'America/New_York', name: 'Eastern Time (US / Canada)', utcOffset: '-05:00', city: 'New York / Toronto', badge: 'US', flag: 'US', shortCode: 'EST' },
  { code: 'America/Chicago', name: 'Central Time (US)', utcOffset: '-06:00', city: 'Chicago / Dallas', badge: 'US', flag: 'US', shortCode: 'CST' },
  { code: 'America/Los_Angeles', name: 'Pacific Time (US / Canada)', utcOffset: '-08:00', city: 'Los Angeles / SF', badge: 'US', flag: 'US', shortCode: 'PST' },
  { code: 'Europe/London', name: 'Greenwich Mean Time (GMT/BST)', utcOffset: '+00:00', city: 'London / Dublin', badge: 'GB', flag: 'GB', shortCode: 'GMT' },
  { code: 'Europe/Paris', name: 'Central European Time (CET)', utcOffset: '+01:00', city: 'Paris / Berlin / Rome', badge: 'EU', flag: 'EU', shortCode: 'CET' },
  { code: 'Asia/Dubai', name: 'Gulf Standard Time (GST)', utcOffset: '+04:00', city: 'Dubai / Abu Dhabi', badge: 'AE', flag: 'AE', shortCode: 'GST' },
  { code: 'Asia/Singapore', name: 'Singapore Standard Time (SGT)', utcOffset: '+08:00', city: 'Singapore', badge: 'SG', flag: 'SG', shortCode: 'SGT' },
  { code: 'Australia/Sydney', name: 'Australian Eastern Time (AEST)', utcOffset: '+10:00', city: 'Sydney / Melbourne', badge: 'AU', flag: 'AU', shortCode: 'AEST' },
  { code: 'Asia/Tokyo', name: 'Japan Standard Time (JST)', utcOffset: '+09:00', city: 'Tokyo', badge: 'JP', flag: 'JP', shortCode: 'JST' },
];

export interface ResolvedTimeZone {
  iana: string;
  offsetMinutes: number;
  label: string;
  utcOffset: string;
  name: string;
}

/**
 * Normalizes any free-form timezone string (e.g. "IST (UTC+5:30)", "Asia/Kolkata", "AEST", "+10:00")
 * to a guaranteed valid IANA code, minute offset, and short label.
 */
export function resolveTimeZone(tzInput?: string): ResolvedTimeZone {
  if (!tzInput || typeof tzInput !== 'string') {
    return { iana: 'Asia/Kolkata', offsetMinutes: 330, label: 'IST', utcOffset: '+05:30', name: 'India Standard Time (IST)' };
  }

  const raw = tzInput.trim();

  // 1. Direct match with POPULAR_TIMEZONES by code or shortCode
  const directMatch = POPULAR_TIMEZONES.find(
    (t) => t.code.toLowerCase() === raw.toLowerCase() || t.shortCode.toLowerCase() === raw.toLowerCase()
  );
  if (directMatch) {
    const offsetMins = parseUtcOffsetToMinutes(directMatch.utcOffset);
    return {
      iana: directMatch.code,
      offsetMinutes: offsetMins,
      label: directMatch.shortCode,
      utcOffset: directMatch.utcOffset,
      name: directMatch.name
    };
  }

  const lower = raw.toLowerCase();

  // 2. Substring & Keyword matching
  if (lower.includes('kolkata') || lower.includes('ist') || lower.includes('india') || lower.includes('calcutta')) {
    return { iana: 'Asia/Kolkata', offsetMinutes: 330, label: 'IST', utcOffset: '+05:30', name: 'India Standard Time (IST)' };
  }
  if (lower.includes('sydney') || lower.includes('aest') || lower.includes('melbourne') || lower.includes('australia')) {
    return { iana: 'Australia/Sydney', offsetMinutes: 600, label: 'AEST', utcOffset: '+10:00', name: 'Australian Eastern Time (AEST)' };
  }
  if (lower.includes('new_york') || lower.includes('eastern') || lower.includes('est') || lower.includes('toronto')) {
    return { iana: 'America/New_York', offsetMinutes: -300, label: 'EST', utcOffset: '-05:00', name: 'Eastern Time (EST)' };
  }
  if (lower.includes('chicago') || lower.includes('central') || lower.includes('cst') || lower.includes('dallas')) {
    return { iana: 'America/Chicago', offsetMinutes: -360, label: 'CST', utcOffset: '-06:00', name: 'Central Time (CST)' };
  }
  if (lower.includes('los_angeles') || lower.includes('pacific') || lower.includes('pst') || lower.includes('san francisco')) {
    return { iana: 'America/Los_Angeles', offsetMinutes: -480, label: 'PST', utcOffset: '-08:00', name: 'Pacific Time (PST)' };
  }
  if (lower.includes('london') || lower.includes('gmt') || lower.includes('bst') || lower.includes('greenwich') || lower.includes('dublin')) {
    return { iana: 'Europe/London', offsetMinutes: 0, label: 'GMT', utcOffset: '+00:00', name: 'Greenwich Mean Time (GMT)' };
  }
  if (lower.includes('paris') || lower.includes('cet') || lower.includes('berlin') || lower.includes('rome')) {
    return { iana: 'Europe/Paris', offsetMinutes: 60, label: 'CET', utcOffset: '+01:00', name: 'Central European Time (CET)' };
  }
  if (lower.includes('dubai') || lower.includes('gst') || lower.includes('abu dhabi') || lower.includes('gulf')) {
    return { iana: 'Asia/Dubai', offsetMinutes: 240, label: 'GST', utcOffset: '+04:00', name: 'Gulf Standard Time (GST)' };
  }
  if (lower.includes('singapore') || lower.includes('sgt')) {
    return { iana: 'Asia/Singapore', offsetMinutes: 480, label: 'SGT', utcOffset: '+08:00', name: 'Singapore Standard Time (SGT)' };
  }
  if (lower.includes('tokyo') || lower.includes('jst') || lower.includes('japan')) {
    return { iana: 'Asia/Tokyo', offsetMinutes: 540, label: 'JST', utcOffset: '+09:00', name: 'Japan Standard Time (JST)' };
  }

  // 3. Parse explicit offset patterns: UTC+05:30, +10:00, -05:00, etc.
  const offsetMatch = raw.match(/(?:UTC|GMT)?\s*([+-])\s*(\d{1,2})(?::(\d{2}))?/i);
  if (offsetMatch) {
    const sign = offsetMatch[1] === '-' ? -1 : 1;
    const hours = parseInt(offsetMatch[2], 10);
    const mins = offsetMatch[3] ? parseInt(offsetMatch[3], 10) : 0;
    const totalMinutes = sign * (hours * 60 + mins);
    const formattedOffset = `${sign < 0 ? '-' : '+'}${String(hours).padStart(2, '0')}:${String(mins).padStart(2, '0')}`;
    return {
      iana: 'UTC',
      offsetMinutes: totalMinutes,
      label: `UTC${formattedOffset}`,
      utcOffset: formattedOffset,
      name: `Custom Timezone (${formattedOffset})`
    };
  }

  // Fallback
  return { iana: 'Asia/Kolkata', offsetMinutes: 330, label: 'IST', utcOffset: '+05:30', name: 'India Standard Time (IST)' };
}

/**
 * Helper to parse "+05:30" or "-05:00" to minutes from UTC.
 */
function parseUtcOffsetToMinutes(offsetStr: string): number {
  const match = offsetStr.match(/([+-])(\d{2}):(\d{2})/);
  if (!match) return 0;
  const sign = match[1] === '-' ? -1 : 1;
  const hours = parseInt(match[2], 10);
  const minutes = parseInt(match[3], 10);
  return sign * (hours * 60 + minutes);
}

/**
 * Detect client's browser local time zone safely.
 */
export function getClientLocalTimeZone(): string {
  if (typeof Intl !== 'undefined' && Intl.DateTimeFormat) {
    try {
      const detected = Intl.DateTimeFormat().resolvedOptions().timeZone;
      if (detected) return detected;
    } catch {}
  }
  return 'Asia/Kolkata';
}

/**
 * Parses time strings like "10:00 AM", "03:30 PM", or "14:00" to minutes from midnight.
 */
export function parseTimeToMinutes(timeStr: string): number {
  const clean = timeStr.trim().toUpperCase();
  const isPM = clean.includes('PM');
  const isAM = clean.includes('AM');

  const match = clean.match(/(\d{1,2}):(\d{2})/);
  if (!match) return 600; // 10:00 AM fallback

  let hours = parseInt(match[1], 10);
  const minutes = parseInt(match[2], 10);

  if (isPM && hours < 12) hours += 12;
  if (isAM && hours === 12) hours = 0;

  return hours * 60 + minutes;
}

/**
 * Formats minutes from midnight to readable string (e.g. 630 -> "10:30 AM")
 */
export function formatMinutesToTime(totalMinutes: number): string {
  let normalized = totalMinutes % (24 * 60);
  if (normalized < 0) normalized += 24 * 60;

  const hours24 = Math.floor(normalized / 60);
  const minutes = normalized % 60;

  const period = hours24 >= 12 ? 'PM' : 'AM';
  let hours12 = hours24 % 12;
  if (hours12 === 0) hours12 = 12;

  const paddedMin = String(minutes).padStart(2, '0');
  return `${hours12}:${paddedMin} ${period}`;
}

export interface SlotConversionResult {
  clientTime: string;
  coachTime: string;
  coachLabel: string;
  clientLabel: string;
  dayShift: string;
  timeDifferenceText: string;
  isSameZone: boolean;
}

/**
 * Converts a slot time from coach's time zone to client's time zone with full metadata.
 */
export function convertSlotToClientTimeZone(
  coachTimeStr: string,
  coachTimeZone: string = 'Asia/Kolkata',
  clientTimeZone: string = 'Asia/Kolkata'
): SlotConversionResult {
  const coachTz = resolveTimeZone(coachTimeZone);
  const clientTz = resolveTimeZone(clientTimeZone);

  const isSameZone = coachTz.offsetMinutes === clientTz.offsetMinutes;

  if (isSameZone) {
    return {
      clientTime: coachTimeStr,
      coachTime: coachTimeStr,
      coachLabel: coachTz.label,
      clientLabel: clientTz.label,
      dayShift: '',
      timeDifferenceText: 'Same Time Zone',
      isSameZone: true
    };
  }

  const coachMinutes = parseTimeToMinutes(coachTimeStr);
  const offsetDiffMinutes = clientTz.offsetMinutes - coachTz.offsetMinutes;
  const clientMinutes = coachMinutes + offsetDiffMinutes;

  let dayShift = '';
  if (clientMinutes < 0) {
    dayShift = ' (Previous Day)';
  } else if (clientMinutes >= 24 * 60) {
    dayShift = ' (Next Day)';
  }

  const formattedClientTime = formatMinutesToTime(clientMinutes);

  const diffHours = Math.abs(offsetDiffMinutes) / 60;
  const diffStr = Number.isInteger(diffHours) ? `${diffHours}` : diffHours.toFixed(1);
  const timeDifferenceText = offsetDiffMinutes > 0
    ? `You are ${diffStr}h ahead of coach`
    : `You are ${diffStr}h behind coach`;

  return {
    clientTime: formattedClientTime,
    coachTime: coachTimeStr,
    coachLabel: coachTz.label,
    clientLabel: clientTz.label,
    dayShift,
    timeDifferenceText,
    isSameZone: false
  };
}

/**
 * Formats the current real-time clock in a target time zone (e.g. "03:45 PM")
 * Never throws, always produces a valid, accurate string.
 */
export function getCurrentTimeInZone(timeZone: string = 'Asia/Kolkata'): string {
  const tz = resolveTimeZone(timeZone);

  try {
    return new Intl.DateTimeFormat('en-US', {
      timeZone: tz.iana,
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    }).format(new Date());
  } catch {
    // Exact UTC computation fallback
    const now = new Date();
    const utcMinutes = now.getUTCHours() * 60 + now.getUTCMinutes();
    return formatMinutesToTime(utcMinutes + tz.offsetMinutes);
  }
}
