import React, { useEffect } from 'react';
import { BrowserRouter, Routes, Route, useLocation } from 'react-router-dom';
import { AppProvider, useApp } from 'context/AppContext';
import LayoutWrapper from 'components/LayoutWrapper';

// Page components
import HomePage from 'pages/page';
import AboutPage from 'pages/about/page';
import AdminPage from 'pages/admin/page';
import AdminLoginPage from 'pages/admin/login/page';
import BlogPage from 'pages/blog/page';
import BlogPostPage from 'pages/blog/[slug]/page';
import CoachesPage from 'pages/coaches/page';
import CoachDetailPage from 'pages/coaches/[id]/page';
import CommunityGuidelinesPage from 'pages/community-guidelines/page';
import ContactPage from 'pages/contact/page';
import ClientDashboardPage from 'pages/dashboard/client/page';
import CoachDashboardPage from 'pages/dashboard/coach/page';
import EbooksPage from 'pages/ebooks/page';
import HowItWorksPage from 'pages/how-it-works/page';
import InvoicesPage from 'pages/invoices/page';
import JoinCoachPage from 'pages/join-coach/page';
import PrivacyPage from 'pages/privacy/page';
import RefundPolicyPage from 'pages/refund-policy/page';
import TermsPage from 'pages/terms/page';
import VerificationStandardsPage from 'pages/verification-standards/page';

function ScrollToTop() {
  const { pathname } = useLocation();
  useEffect(() => {
    window.scrollTo(0, 0);
  }, [pathname]);
  return null;
}

function GlobalApiErrorBanner() {
  const { apiError, clearApiError } = useApp();
  if (!apiError) return null;
  return (
    <div
      role="alert"
      className="fixed bottom-5 right-5 z-[9999] max-w-md bg-red-600 text-white px-4 py-3.5 rounded-2xl shadow-2xl border border-red-400 flex items-start gap-3 animate-in fade-in slide-in-from-bottom-4"
    >
      <span className="inline-flex shrink-0 w-6 h-6 rounded-full bg-white/20 items-center justify-center font-black text-xs mt-0.5">
        !
      </span>
      <div className="flex-1 text-xs sm:text-sm font-semibold leading-snug">
        <p className="font-black uppercase tracking-wider text-[10px] text-red-100 mb-0.5">System / API Warning</p>
        <p>{apiError}</p>
      </div>
      <button
        onClick={clearApiError}
        aria-label="Dismiss error"
        className="shrink-0 text-white/80 hover:text-white font-bold text-sm px-1.5 py-0.5 rounded-lg hover:bg-white/10"
      >
        ✕
      </button>
    </div>
  );
}

export default function App() {
  return (
    <BrowserRouter>
      <ScrollToTop />
      <AppProvider>
        <GlobalApiErrorBanner />
        <LayoutWrapper>
          <Routes>
            <Route path="/" element={<HomePage />} />
            <Route path="/about" element={<AboutPage />} />
            <Route path="/admin" element={<AdminPage />} />
            <Route path="/admin/login" element={<AdminLoginPage />} />
            <Route path="/blog" element={<BlogPage />} />
            <Route path="/blog/:slug" element={<BlogPostPage />} />
            <Route path="/coaches" element={<CoachesPage />} />
            <Route path="/coaches/:id" element={<CoachDetailPage />} />
            <Route path="/community-guidelines" element={<CommunityGuidelinesPage />} />
            <Route path="/contact" element={<ContactPage />} />
            <Route path="/dashboard/client" element={<ClientDashboardPage />} />
            <Route path="/dashboard/coach" element={<CoachDashboardPage />} />
            <Route path="/ebooks" element={<EbooksPage />} />
            <Route path="/how-it-works" element={<HowItWorksPage />} />
            <Route path="/invoices" element={<InvoicesPage />} />
            <Route path="/join-coach" element={<JoinCoachPage />} />
            <Route path="/privacy" element={<PrivacyPage />} />
            <Route path="/refund-policy" element={<RefundPolicyPage />} />
            <Route path="/terms" element={<TermsPage />} />
            <Route path="/verification-standards" element={<VerificationStandardsPage />} />
            <Route path="*" element={<HomePage />} />
          </Routes>
        </LayoutWrapper>
      </AppProvider>
    </BrowserRouter>
  );
}

